-- Listage de la structure de table fruitiva. acc_ia_propositions
CREATE TABLE IF NOT EXISTS `acc_ia_propositions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `item_id` bigint(20) unsigned NOT NULL,
  `contenu` text NOT NULL,
  `type` enum('amelioration','validation','alerte') NOT NULL DEFAULT 'amelioration',
  `priorite` enum('haute','moyenne','faible') NOT NULL DEFAULT 'moyenne',
  `actions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`actions`)),
  `indicateurs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`indicateurs`)),
  `echeance` varchar(50) DEFAULT NULL,
  `generated_by` varchar(100) NOT NULL DEFAULT 'mistral',
  `generated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `is_accepted` tinyint(1) DEFAULT NULL,
  `accepted_by` bigint(20) unsigned DEFAULT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_acc_ia_item` (`item_id`),
  KEY `idx_acc_ia_type` (`type`),
  KEY `idx_acc_ia_priorite` (`priorite`),
  CONSTRAINT `fk_acc_ia_item` FOREIGN KEY (`item_id`) REFERENCES `acc_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

