-- Listage de la structure de table fruitiva. acc_items
CREATE TABLE IF NOT EXISTS `acc_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `acc_id` bigint(20) unsigned NOT NULL,
  `type` enum('section','item') NOT NULL DEFAULT 'item',
  `ref_article` varchar(50) DEFAULT NULL COMMENT 'Ex: QHS 1',
  `libelle_norme` varchar(500) DEFAULT NULL COMMENT 'Libellé de la section',
  `exigence_norme` text DEFAULT NULL COMMENT 'Texte complet de l''exigence',
  `reponse` enum('O','N','SO') DEFAULT NULL COMMENT 'O=Conforme, N=Non conforme, SO=Sans objet',
  `forces` text DEFAULT NULL,
  `faiblesses` text DEFAULT NULL,
  `objectif` text DEFAULT NULL COMMENT 'Objectif de contrôle',
  `observations` text DEFAULT NULL,
  `score` tinyint(4) DEFAULT NULL COMMENT '100=O, 0=N, 50=SO',
  `ordre` smallint(6) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_acc_items_acc` (`acc_id`),
  KEY `idx_acc_items_reponse` (`reponse`),
  KEY `idx_acc_items_ordre` (`acc_id`,`ordre`),
  CONSTRAINT `fk_acc_items_acc` FOREIGN KEY (`acc_id`) REFERENCES `mission_phase_acc` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

