  CONSTRAINT `activity_raci_session_assignments_session_id_foreign` FOREIGN KEY (`session_id`) REFERENCES `process_evaluation_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

