  `entity_id` bigint(20) unsigned NOT NULL,
  `function_id` bigint(20) unsigned NOT NULL,
  `total_count` int(11) NOT NULL DEFAULT 0,
  `phase1_count` int(11) NOT NULL DEFAULT 0,
  `phase2_count` int(11) NOT NULL DEFAULT 0,
  `phase3_count` int(11) NOT NULL DEFAULT 0,
  `completed_count` int(11) NOT NULL DEFAULT 0,
  `average_criticality_before` decimal(5,2) DEFAULT NULL,
  `average_criticality_after` decimal(5,2) DEFAULT NULL,
  `average_improvement` decimal(5,2) DEFAULT NULL,
  `alert_before_vert` int(11) NOT NULL DEFAULT 0,
  `alert_before_bleu` int(11) NOT NULL DEFAULT 0,
  `alert_before_jaune` int(11) NOT NULL DEFAULT 0,
  `alert_before_orange` int(11) NOT NULL DEFAULT 0,
  `alert_before_rouge` int(11) NOT NULL DEFAULT 0,
  `alert_after_vert` int(11) NOT NULL DEFAULT 0,
  `alert_after_bleu` int(11) NOT NULL DEFAULT 0,
  `alert_after_jaune` int(11) NOT NULL DEFAULT 0,
  `alert_after_orange` int(11) NOT NULL DEFAULT 0,
  `alert_after_rouge` int(11) NOT NULL DEFAULT 0,
  `current_phase` enum('PHASE1','PHASE2','PHASE3','CLOSED') NOT NULL DEFAULT 'PHASE1',
  `phase1_started_at` timestamp NULL DEFAULT NULL,
  `phase2_started_at` timestamp NULL DEFAULT NULL,
  `phase3_started_at` timestamp NULL DEFAULT NULL,
  `status` enum('in_progress','on_hold','completed','archived') NOT NULL DEFAULT 'in_progress',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_amdec_session_process` (`session_id`,`process_id`),
  KEY `amdec_phase_tracking_session_id_index` (`session_id`),
  KEY `amdec_phase_tracking_process_id_index` (`process_id`),
  KEY `amdec_phase_tracking_entity_id_index` (`entity_id`),
  KEY `amdec_phase_tracking_function_id_index` (`function_id`),
  KEY `amdec_phase_tracking_current_phase_index` (`current_phase`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

