-- Listage de la structure de table fruitiva. amdec_records
CREATE TABLE IF NOT EXISTS `amdec_records` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `session_id` bigint(20) unsigned NOT NULL,
  `process_id` bigint(20) unsigned NOT NULL,
  `activity_id` bigint(20) unsigned DEFAULT NULL,
  `entity_id` bigint(20) unsigned NOT NULL,
  `function_id` bigint(20) unsigned NOT NULL,
  `phase` enum('PHASE1','PHASE2','PHASE3') NOT NULL DEFAULT 'PHASE1',
  `mode_number` int(11) DEFAULT NULL,
  `failure_mode` varchar(255) NOT NULL,
  `failure_description` text DEFAULT NULL,
  `effects` text DEFAULT NULL,
  `causes` text DEFAULT NULL,
  `current_controls` text DEFAULT NULL,
  `gravity_before_id` bigint(20) unsigned DEFAULT NULL,
  `gravity_score_before` tinyint(4) DEFAULT NULL,
  `frequency_before_id` bigint(20) unsigned DEFAULT NULL,
  `frequency_score_before` tinyint(4) DEFAULT NULL,
  `detectability_before_id` bigint(20) unsigned DEFAULT NULL,
  `detectability_score_before` tinyint(4) DEFAULT NULL,
  `criticality_before` int(11) DEFAULT NULL,
  `criticality_nette_before` decimal(5,2) DEFAULT NULL,
  `standard_before_id` bigint(20) unsigned DEFAULT NULL,
  `alert_level_before` varchar(50) DEFAULT NULL,
  `prevention_measures` text DEFAULT NULL,
  `detection_measures` text DEFAULT NULL,
  `action_responsible` varchar(255) DEFAULT NULL,
  `action_deadline` date DEFAULT NULL,
  `implemented_prevention_measures` text DEFAULT NULL,
  `implemented_detection_measures` text DEFAULT NULL,
  `actual_completion_date` date DEFAULT NULL,
  `gravity_after_id` bigint(20) unsigned DEFAULT NULL,
  `gravity_score_after` tinyint(4) DEFAULT NULL,
  `frequency_after_id` bigint(20) unsigned DEFAULT NULL,
  `frequency_score_after` tinyint(4) DEFAULT NULL,
  `detectability_after_id` bigint(20) unsigned DEFAULT NULL,
  `detectability_score_after` tinyint(4) DEFAULT NULL,
  `criticality_after` int(11) DEFAULT NULL,
  `criticality_nette_after` decimal(5,2) DEFAULT NULL,
  `standard_after_id` bigint(20) unsigned DEFAULT NULL,
  `alert_level_after` varchar(50) DEFAULT NULL,
  `improvement_percentage` decimal(5,2) DEFAULT NULL,
  `action_status` enum('pending','in_progress','completed','cancelled') NOT NULL DEFAULT 'pending',
  `is_phase2_approved` tinyint(1) NOT NULL DEFAULT 0,
  `is_closed` tinyint(1) NOT NULL DEFAULT 0,
  `created_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `created_by_user_name` varchar(255) DEFAULT NULL,
  `updated_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `updated_by_user_name` varchar(255) DEFAULT NULL,
  `closed_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `closed_by_user_name` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_amdec_context` (`session_id`,`process_id`,`activity_id`),
  KEY `idx_amdec_phase_status` (`phase`,`action_status`),
  KEY `amdec_records_session_id_index` (`session_id`),
  KEY `amdec_records_process_id_index` (`process_id`),
  KEY `amdec_records_activity_id_index` (`activity_id`),
  KEY `amdec_records_entity_id_index` (`entity_id`),
  KEY `amdec_records_function_id_index` (`function_id`),
  KEY `amdec_records_phase_index` (`phase`),
  KEY `amdec_records_mode_number_index` (`mode_number`),
