  KEY `idx_amq_marches_amq` (`amq_id`),
  KEY `idx_amq_marches_ref` (`reference`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Marchés analysés dans un QEM';

