  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_ac_soumis_par` (`soumis_par`),
  KEY `fk_ac_valide_par` (`valide_par`),
  KEY `fk_ac_created_by` (`created_by`),
  KEY `idx_ac_statut` (`statut`),
  KEY `idx_ac_date_audit` (`date_audit`),
  KEY `idx_ac_auditeur` (`auditeur_id`),
  CONSTRAINT `fk_ac_auditeur` FOREIGN KEY (`auditeur_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_ac_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_ac_soumis_par` FOREIGN KEY (`soumis_par`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_ac_valide_par` FOREIGN KEY (`valide_par`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

