  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `analyse_conformite_id` bigint(20) unsigned NOT NULL,
  `phase_id` bigint(20) unsigned DEFAULT NULL,
  `sous_phase_id` bigint(20) unsigned DEFAULT NULL,
  `ref_article` varchar(50) NOT NULL,
  `libelle_norme` varchar(500) NOT NULL,
  `exigence_norme` text NOT NULL,
  `reponse` enum('O','N','SO') DEFAULT NULL COMMENT 'O=Oui/Conforme, N=Non-conforme, SO=Sans Objet',
  `forces` text DEFAULT NULL,
  `faiblesses` text DEFAULT NULL,
  `objectif` text DEFAULT NULL COMMENT 'Objectif de contrôle',
  `observations` text DEFAULT NULL,
  `score` tinyint(4) DEFAULT NULL COMMENT '0=N, 50=SO, 100=O',
  `ordre` smallint(6) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_item_sous_phase` (`sous_phase_id`),
  KEY `idx_item_ac` (`analyse_conformite_id`),
  KEY `idx_item_phase` (`phase_id`),
  KEY `idx_item_reponse` (`reponse`),
  KEY `idx_item_score` (`score`),
  CONSTRAINT `fk_item_ac` FOREIGN KEY (`analyse_conformite_id`) REFERENCES `analyse_conformites` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_item_phase` FOREIGN KEY (`phase_id`) REFERENCES `qcc_phases` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_item_sous_phase` FOREIGN KEY (`sous_phase_id`) REFERENCES `qcc_sous_phases` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

