	(1, 9, 1, 'PROC-001', 'Procedure_Conge_RH-PROC-012', 'v1.0', '', '', NULL, NULL, 'Procédure: Procedure_Conge_RH-PROC-012', NULL, NULL, NULL, 'en_cours', '', NULL, 'conforme', 'modere', 'insuffisant', 'recommandation', '', '["Validation hiérarchique systématique des demandes de congés (n+1) avec preuve documentaire","Intégration d’un contrôle automatisé des soldes de congés dans le SIRH (alerte en cas de dépassement)","Archivage centralisé et sécurisé des justificatifs (3 ans) conforme à la RGPD","Procédure alignée sur le Code du travail (art. L3141-1 à L3141-24) et la convention collective applicable","Formation annuelle des managers RH sur les règles de gestion des congés (traçabilité via LMS)"]', '["Absence de revue périodique formelle des comptes de congés par l’audit interne (risque d’erreurs cumulatives)","Délai de traitement des demandes > 48h dans 20% des cas (non-respect du SLA interne de 24h)","Pas de contrôle croisé entre les congés payés et les arrêts maladie (risque de fraude ou double indemnisation)","Procédure silencieuse sur la gestion des congés exceptionnels (ex. décès, mariage) – discrétionnaire sans cadre","Accès non restreint au module SIRH pour certains profils non-RH (violation du principe de moindre privilège)"]', '2026-03-26 00:14:38', '2026-04-11 10:10:27');

-- Listage de la structure de table fruitiva. apt_procedure_assignments
CREATE TABLE IF NOT EXISTS `apt_procedure_assignments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `apt_id` bigint(20) unsigned NOT NULL COMMENT 'FK → mission_phase_apt.id',
  `procedure_id` bigint(20) unsigned NOT NULL COMMENT 'FK → apt_procedures.id',
  `auditeur_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK → auditors.id — auditeur responsable de la procédure',
  `affecte_par` bigint(20) unsigned DEFAULT NULL COMMENT 'FK → auditors.id — DM ou CM ayant fait l''affectation',
  `date_affectation` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_apt_proc_assign` (`apt_id`,`procedure_id`),
  KEY `idx_aptpa_apt` (`apt_id`),
  KEY `idx_aptpa_procedure` (`procedure_id`),
  KEY `idx_aptpa_auditeur` (`auditeur_id`),
  KEY `idx_aptpa_affecte_par` (`affecte_par`),
  CONSTRAINT `fk_aptpa_affecte_par` FOREIGN KEY (`affecte_par`) REFERENCES `auditors` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_aptpa_apt` FOREIGN KEY (`apt_id`) REFERENCES `mission_phase_apt` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_aptpa_auditeur` FOREIGN KEY (`auditeur_id`) REFERENCES `auditors` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_aptpa_procedure` FOREIGN KEY (`procedure_id`) REFERENCES `apt_procedures` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Affecte une procédure APT à un auditeur de la phase. DM/CM gèrent; AS/AJ éditent uniquement les leurs.';

