-- Listage des données de la table fruitiva.ap_criteres : ~6 rows (environ)
INSERT INTO `ap_criteres` (`id`, `code`, `nature`, `description`, `but`, `norme`, `beneficiaire_code`, `sort`, `created_at`, `updated_at`) VALUES
	(1, 'ECO', 'Économie', 'Le principe d\'économie consiste à réduire au minimum le coût des ressources. Les moyens mis en oeuvre doivent être rendus disponibles en temps utile, dans les quantités et qualités appropriées et au meilleur prix.', 'Conformité procédures', 'ISSAI 300/11', 'Rsp', 1, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(2, 'EFE', 'Efficience', 'Le principe d\'efficience consiste à obtenir le maximum à partir des ressources disponibles. Il porte sur le rapport entre les moyens mis en oeuvre et les réalisations sur le plan de la quantité, de la qualité et du respect des échéances.', 'Rentabilité des moyens', 'ISSAI 300/11', 'Con', 2, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(3, 'EFK', 'Efficacité', 'Le principe d\'efficacité concerne la réalisation des objectifs fixés et l\'obtention des résultats escomptés.', 'Atteinte des objectifs', 'ISSAI 300/11', 'Cit', 3, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(4, 'QDS', 'Qualité de service', 'Standards de qualité visés dans le champ concerné, qualité attendue du service rendu à l\'usager, c\'est-à-dire l\'aptitude à satisfaire son bénéficiaire.', 'Satisfaction du bénéficiaire', NULL, 'Usr', 4, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(5, 'EQT', 'Équité', NULL, 'Équité', NULL, 'Usr', 5, '2026-07-03 14:03:50', '2026-07-03 14:03:50'),
	(6, 'ENV', 'Environnement', NULL, 'Environnement', 'ISO 14001', 'Cit', 6, '2026-07-03 14:05:19', '2026-07-03 14:05:19');

-- Listage de la structure de table fruitiva. ap_facteurs_selection_theme
CREATE TABLE IF NOT EXISTS `ap_facteurs_selection_theme` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(30) NOT NULL,
  `libelle` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `sort` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
