) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Listage des données de la table fruitiva.ap_facteurs_selection_theme : ~10 rows (environ)
INSERT INTO `ap_facteurs_selection_theme` (`id`, `code`, `libelle`, `description`, `sort`, `created_at`, `updated_at`) VALUES
	(1, 'SIGNIFICATIF', 'Caractère significatif', 'Importance relative d\'un sujet en fonction du contexte dans lequel il est considéré (valeur monétaire, enjeux social, politique, conformité, transparence, gouvernance, redevabilité).', 1, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(2, 'AUDITABILITE', 'Auditabilité', 'Le sujet peut-il être audité ? L\'audit est-il réalisable ? Entre-t-il dans le mandat juridique de l\'ISC ? L\'ISC a-t-elle la capacité nécessaire ?', 2, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(3, 'IMPACT', 'Impact possible', 'Le sujet aura-t-il une forte incidence sur l\'amélioration de l\'économie, de l\'efficience et/ou de l\'efficacité de l\'action publique ?', 3, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(4, 'RISQUE_ISC', 'Risques pour l\'ISC', 'La réalisation d\'un audit sur le sujet peut-elle présenter un risque pour l\'ISC (sur le plan stratégique ou pour sa réputation) ?', 4, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(5, 'INTERET_PUBLIC', 'Intérêt du pouvoir législatif ou du public', 'L\'audit du sujet répondra-t-il à une problématique juridique ou présentera-t-il un avantage pour la communauté ?', 5, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(6, 'PERTINENCE', 'Pertinence', 'Le sujet a-t-il un impact ou une importance pour des problèmes du monde réel, des événements actuels ou la situation actuelle de la société ?', 6, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(7, 'OPPORTUNITE', 'Opportunité', 'Le moment est-il bien choisi pour auditer le sujet ? Par exemple, est-il trop tôt pour évaluer les progrès réalisés par une nouvelle activité ?', 7, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(8, 'TRAVAIL_ANTERIEUR', 'Travail d\'audit antérieur', 'Le sujet a-t-il déjà été audité par le passé ? Est-il utile de l\'auditer à nouveau ? Est-il possible d\'adopter une nouvelle approche ?', 8, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(9, 'DEMANDE', 'Demande d\'audits de la performance', 'A-t-on formulé des demandes spécifiques visant la réalisation d\'audits de la performance (pouvoir législatif, bénéficiaires, parties prenantes externes) ?', 9, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(10, 'AUTRE_TRAVAIL', 'Autre travail important programmé ou en cours', 'A-t-on programmé ou réalisé d\'autres travaux sur ce sujet ?', 10, '2026-07-03 13:03:39', '2026-07-03 13:03:39');

