INSERT INTO `ap_methodes_analyse` (`id`, `code`, `libelle`, `description`, `type`, `sort`, `created_at`, `updated_at`) VALUES
	(1, 'CONT', 'Analyse de contenus', 'Utilisation de logiciels et de modèles informatiques pour identifier des tendances, des schémas et des corrélations dans les grands ensembles de données.', 'qualitative', 1, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(2, 'STAT', 'Analyse et modélisation statistique', 'Examen statistique et modélisation des données recueillies pour produire des tendances, ratios ou indicateurs.', 'quantitative', 2, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(3, 'SYST', 'Analyse de systèmes', NULL, 'quantitative', 3, '2026-07-03 14:31:05', '2026-07-03 14:31:47'),
