INSERT INTO `ap_methodes_collecte` (`id`, `code`, `libelle`, `description`, `sort`, `created_at`, `updated_at`) VALUES
	(1, 'Ent', 'Entretiens', 'Discussion avec une ou plusieurs personnes, par téléphone ou en personne, pour recueillir une opinion sur un programme ou une activité.', 1, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(2, 'Doc', 'Collecte de documents', 'Examen de documents collectés auprès de l\'entité contrôlée et d\'autres sources.', 2, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(3, 'Obs', 'Observations directes ou inspection', 'Observation physique de dispositifs, de personnes, de bâtiments et d\'événements liés à l\'audit, afin de recueillir des informations qualitatives.', 3, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(4, 'Enq', 'Enquêtes', 'Approche de la collecte d\'informations ou de données utilisées pour recueillir des éléments probants auprès d\'une population à l\'aide d\'un ensemble de questions prédéfinies.', 4, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(5, 'Exa', 'Examens de dossiers et observations structurées', 'Outils de collecte d\'informations ou de données utilisées pour enregistrer systématiquement des observations et des informations extraites de documents.', 5, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(6, 'Grp', 'Groupe restreint (focus)', 'Collecte d\'informations auprès d\'un groupe de personnes à l\'aide d\'outils comme le groupe de discussion ou le panel d\'experts extérieurs à l\'ISC.', 6, '2026-07-03 13:03:39', '2026-07-03 14:21:01'),
	(7, 'Dos', 'Données secondaires', 'Données recueillies par universités, instituts de recherche.', 7, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(8, 'Edc', 'Étude de cas', 'Collecte rigoureuse de données correspondant à un ou plusieurs événements, problèmes ou sites complexes, pour répondre à des questions complexes du type « pourquoi » ou « comment ».', 8, '2026-07-03 13:03:39', '2026-07-03 13:03:39');

