-- Listage des données de la table fruitiva.ap_perimetre_dimensions : ~4 rows (environ)
INSERT INTO `ap_perimetre_dimensions` (`id`, `code`, `libelle`, `questions_cles`, `sort`, `created_at`, `updated_at`) VALUES
	(1, 'QUI', 'Qui', 'Quelles agences et organisations ont des responsabilités ou des points de vue pertinents pour l\'audit ?\nParmi ces agences, lesquelles sont les mieux à même de fournir des éléments probants suffisants et appropriés ?\nQui a la responsabilité d\'assurer la fiabilité des informations et données pertinentes ?', 1, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(2, 'QUOI', 'Quoi', 'Quelles sont précisément les questions ou hypothèses examinées ?\nQuels sont les principaux processus pertinents pour l\'audit ?\nQuel est le sujet considéré par l\'évaluation et la présentation des résultats ?\nQuelles sont les ressources disponibles pour réaliser l\'audit ?', 2, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(3, 'QUAND', 'Quand', 'Quelle période l\'audit doit-il couvrir ?', 3, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(4, 'OU', 'Où', 'Quels sont les sites couverts ?\nQuels documents et enregistrements faudra-t-il examiner ?', 4, '2026-07-03 13:03:39', '2026-07-03 13:03:39');

-- Listage de la structure de table fruitiva. ap_risques_audit
CREATE TABLE IF NOT EXISTS `ap_risques_audit` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(20) NOT NULL,
  `libelle` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `sort` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Listage des données de la table fruitiva.ap_risques_audit : ~8 rows (environ)
INSERT INTO `ap_risques_audit` (`id`, `code`, `libelle`, `description`, `sort`, `created_at`, `updated_at`) VALUES
	(1, 'A', 'Conclusions erronées ou incomplètes', 'Les auditeurs parviennent à des conclusions d\'audit erronées ou incomplètes et formulent des recommandations qui ne sont pas axées sur les thèmes à aborder ou sur des questions pertinentes.', 1, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(2, 'B', 'Informations déséquilibrées', 'Les auditeurs omettent de rendre compte des bonnes pratiques et des aspects positifs de l\'action de l\'entité contrôlée ; l\'accent est mis sur les insuffisances sans expliquer les difficultés ou contraintes du contexte.', 2, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(3, 'C', 'Pas ou peu de valeur ajoutée pour les utilisateurs à l\'issue de l\'audit', 'Les auditeurs échouent à produire de nouvelles informations ou connaissances à partir de l\'audit.', 3, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(4, 'D', 'Difficultés à obtenir des informations de qualité', 'Les auditeurs n\'ont pas accès aux informations nécessaires, ou pas suffisamment, ou les informations ne répondent pas aux exigences de qualité.', 4, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(5, 'E', 'Analyse insuffisante', 'Les auditeurs ne réalisent pas une analyse suffisante par manque d\'expertise, de critères d\'audit ou d\'accès à l\'information.', 5, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(6, 'F', 'Omission d\'informations ou d\'arguments pertinents', 'Les auditeurs n\'identifient pas la totalité des thématiques clés à aborder, omettent des éléments probants pertinents ou ne parviennent pas à contrebalancer des arguments importants.', 6, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(7, 'G', 'Présence de cas de fraude, d\'utilisation abusive des ressources et/ou de pratiques irrégulières', 'Les auditeurs n\'évaluent pas si le risque de fraude est important dans le contexte des objectifs de l\'audit et/ou ne communiquent pas rapidement les fraudes et irrégularités constatées.', 7, '2026-07-03 13:03:39', '2026-07-03 13:03:39'),
	(8, 'H', 'Sujet particulièrement complexe ou politiquement sensible', 'Les auditeurs n\'appliquent pas un traitement approprié à des sujets particulièrement complexes ou politiquement sensibles, ce qui peut porter atteinte à la crédibilité du rapport et de l\'ISC.', 8, '2026-07-03 13:03:39', '2026-07-03 13:03:39');

