-- Listage de la structure de table fruitiva. at_process_assignments
CREATE TABLE IF NOT EXISTS `at_process_assignments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `assignment_id` bigint(20) unsigned NOT NULL COMMENT 'FK → mission_phase_assignments.id',
  `process_id` bigint(20) unsigned NOT NULL COMMENT 'FK → processes.id',
  `auditeur_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK → auditors.id — auditeur responsable du processus dans cette phase',
  `affecte_par` bigint(20) unsigned DEFAULT NULL COMMENT 'FK → auditors.id — DM ou CM ayant effectué l''affectation',
  `date_affectation` date DEFAULT NULL COMMENT 'Date à laquelle l''affectation a été faite',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_atpa_assignment_process` (`assignment_id`,`process_id`),
  KEY `idx_atpa_assignment` (`assignment_id`),
  KEY `idx_atpa_process` (`process_id`),
  KEY `idx_atpa_auditeur` (`auditeur_id`),
  KEY `idx_atpa_affecte_par` (`affecte_par`),
  CONSTRAINT `fk_at_proc_assign_affecte_par` FOREIGN KEY (`affecte_par`) REFERENCES `auditors` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_at_proc_assign_assignment` FOREIGN KEY (`assignment_id`) REFERENCES `mission_phase_assignments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_at_proc_assign_auditeur` FOREIGN KEY (`auditeur_id`) REFERENCES `auditors` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_at_proc_assign_process` FOREIGN KEY (`process_id`) REFERENCES `processes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_atpa_affecte_par` FOREIGN KEY (`affecte_par`) REFERENCES `auditors` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_atpa_assignment` FOREIGN KEY (`assignment_id`) REFERENCES `mission_phase_assignments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_atpa_auditeur` FOREIGN KEY (`auditeur_id`) REFERENCES `auditors` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_atpa_process` FOREIGN KEY (`process_id`) REFERENCES `processes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Affectation processus → auditeur pour la matrice RACI AT. DM/CM affectent; AS/AJ voient uniquement leurs processus.';

