-- Listage de la structure de table fruitiva. auditors
CREATE TABLE IF NOT EXISTS `auditors` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Utilisateur associé',
  `entity_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Entité de rattachement',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL COMMENT 'Modifié par',
  `audit_id` varchar(255) NOT NULL COMMENT 'Code auditeur unique (AUD0001)',
  `audit_code` varchar(255) NOT NULL COMMENT 'Code auditeur secondaire',
  `first_name` varchar(255) NOT NULL COMMENT 'Prénom',
  `last_name` varchar(255) NOT NULL COMMENT 'Nom de famille',
  `email` varchar(255) NOT NULL COMMENT 'Email unique',
  `phone` varchar(255) DEFAULT NULL COMMENT 'Téléphone',
  `date_of_birth` date DEFAULT NULL COMMENT 'Date de naissance',
  `birthplace` varchar(255) DEFAULT NULL COMMENT 'Lieu de naissance',
  `gender` enum('M','F') DEFAULT NULL COMMENT 'Genre',
  `address` longtext DEFAULT NULL COMMENT 'Adresse complète',
  `city` varchar(255) DEFAULT NULL COMMENT 'Ville',
  `postal_code` varchar(255) DEFAULT NULL COMMENT 'Code postal',
  `country` varchar(255) DEFAULT NULL COMMENT 'Pays',
  `audit_experience` int(11) NOT NULL DEFAULT 0 COMMENT 'Années d''expérience audit',
  `other_experience` int(11) NOT NULL DEFAULT 0 COMMENT 'Autres années d''expérience',
  `bio` longtext DEFAULT NULL COMMENT 'Biographie',
  `avatar` varchar(255) DEFAULT NULL COMMENT 'Photo de profil (chemin)',
  `status` enum('active','inactive','suspended') NOT NULL DEFAULT 'active' COMMENT 'Statut',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `audit_id` (`audit_id`),
  UNIQUE KEY `audit_code` (`audit_code`),
  UNIQUE KEY `email` (`email`),
  KEY `auditors_updated_by_foreign` (`updated_by`),
  KEY `auditors_audit_id_index` (`audit_id`),
  KEY `auditors_audit_code_index` (`audit_code`),
  KEY `auditors_email_index` (`email`),
  KEY `auditors_status_index` (`status`),
  KEY `auditors_entity_id_index` (`entity_id`),
  KEY `auditors_created_by_index` (`created_by`),
  KEY `auditors_user_id_index` (`user_id`),
  KEY `auditors_created_at_index` (`created_at`),
  KEY `auditors_status_entity_id_index` (`status`,`entity_id`),
  CONSTRAINT `auditors_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `auditors_entity_id_foreign` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`) ON DELETE SET NULL,
  CONSTRAINT `auditors_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `auditors_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

