CREATE TABLE IF NOT EXISTS `audit_process_rankings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `process_id` bigint(20) unsigned NOT NULL,
  `entity_id` bigint(20) unsigned NOT NULL,
  `total_score` decimal(8,2) DEFAULT 0.00 COMMENT 'Somme des scores (nb_facteurs)',
  `average_score` decimal(5,2) DEFAULT 0.00 COMMENT 'Moyenne des scores (total/nb_facteurs)',
  `rating_label` varchar(50) DEFAULT NULL COMMENT 'Label: Faible, Moyen, Bon, Très Bon, Excellent',
  `ranking_position` int(11) DEFAULT NULL COMMENT 'Rang: 1er, 2e, 3e... au sein de l''entité',
  `ranking_percentage` decimal(5,2) DEFAULT NULL COMMENT 'Pourcentage: (position/total)*100',
  `priority_status` enum('Critique','Haute','Moyenne','Basse','N/A') DEFAULT 'N/A',
  `number_of_evaluations` int(11) DEFAULT 0 COMMENT 'Nombre de fois réévalué',
  `last_evaluation_date` date DEFAULT NULL,
  `next_review_date` date DEFAULT NULL COMMENT 'Date proposée pour réévaluation',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_process_entity` (`process_id`,`entity_id`),
  KEY `entity_id_idx` (`entity_id`),
  KEY `average_score_idx` (`average_score`),
  KEY `ranking_position_idx` (`ranking_position`),
  KEY `priority_status_idx` (`priority_status`),
  KEY `last_evaluation_idx` (`last_evaluation_date`),
  CONSTRAINT `fk_apr_entity` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_apr_process` FOREIGN KEY (`process_id`) REFERENCES `processes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Classement & résumé des processus d''audit par entité';

