  KEY `changed_by_idx` (`changed_by`),
  CONSTRAINT `fk_apsh_entity` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_apsh_factor` FOREIGN KEY (`factor_id`) REFERENCES `audit_factors` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_apsh_process` FOREIGN KEY (`process_id`) REFERENCES `processes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Historique complet des modifications d''audit';

