-- Listage de la structure de table fruitiva. bpmn_diagrams
CREATE TABLE IF NOT EXISTS `bpmn_diagrams` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `process_id` bigint(20) unsigned NOT NULL,
  `bpmn_xml` longtext NOT NULL,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `description` varchar(500) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_bpmn_diagrams_process` (`process_id`),
  KEY `idx_bpmn_diagrams_current` (`process_id`,`is_current`),
  KEY `idx_bpmn_diagrams_version` (`process_id`,`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

