-- Listage de la structure de table fruitiva. fiche_observation_ci
CREATE TABLE IF NOT EXISTS `fiche_observation_ci` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT 'Ex: FOCI-ADI002-001',
  `num_foci` varchar(30) DEFAULT NULL COMMENT 'N° FOCI / FRAP affiché',
  `mission_id` bigint(20) unsigned NOT NULL,
  `assignment_id` bigint(20) unsigned NOT NULL,
  `fiche_test_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK mission_phase_fiche_test.id',
  `test_ref` varchar(80) DEFAULT NULL COMMENT 'Référence du test source',
  `obj_num` varchar(20) DEFAULT NULL COMMENT 'N° objectif source',
  `date_observation` date DEFAULT NULL,
  `heure_debut` varchar(10) DEFAULT NULL,
  `heure_fin` varchar(10) DEFAULT NULL,
  `auditeur` varchar(255) DEFAULT NULL,
  `localisation` varchar(255) DEFAULT NULL,
  `interlocuteurs_presents` text DEFAULT NULL,
  `objectif_audit` text DEFAULT NULL,
  `tache_observer` text DEFAULT NULL,
  `elements_verifier` text DEFAULT NULL,
  `pieces_attendues` text DEFAULT NULL,
  `intitule_probleme` text DEFAULT NULL COMMENT 'Intitulé du problème',
  `faits_constates` text DEFAULT NULL COMMENT 'Faits constatés / FAIT FRAP',
  `critere_referentiel` text DEFAULT NULL COMMENT 'Critère / Référentiel (CRITERE FRAP)',
  `cause` text DEFAULT NULL COMMENT 'Causes (CAUSE FRAP)',
  `causes_json` text DEFAULT NULL COMMENT 'JSON array causes cochées',
  `causes_autres` text DEFAULT NULL,
  `impact` text DEFAULT NULL COMMENT 'Impact/Conséquence (IMPACT FRAP)',
  `consequences_json` text DEFAULT NULL COMMENT 'JSON array conséquences cochées',
  `consequences_description` text DEFAULT NULL,
  `niveau_maitrise` varchar(30) DEFAULT NULL COMMENT '1_faible..5_excellent',
  `niveau_controle` varchar(30) DEFAULT NULL COMMENT 'Auto depuis niveau_maitrise',
  `niveau_synthese` varchar(30) DEFAULT NULL COMMENT 'conforme|a_ameliorer|insuffisant|critique',
  `points_forts` text DEFAULT NULL,
  `conclusion` text DEFAULT NULL,
  `recommandation_prelim` text DEFAULT NULL COMMENT 'Recommandation principale',
  `actions_convenues` text DEFAULT NULL COMMENT 'Actions convenues / commentaire audité',
  `date_echeance` date DEFAULT NULL,
  `responsable` varchar(255) DEFAULT NULL,
  `livrable` text DEFAULT NULL,
  `objectif_controle` varchar(255) DEFAULT NULL COMMENT 'Objectif de contrôle (regroupement)',
  `rubrique` varchar(255) DEFAULT NULL,
  `sous_rubrique` varchar(255) DEFAULT NULL,
  `importance` varchar(20) DEFAULT 'moyenne' COMMENT 'elevee|moyenne|faible',
  `impact_financier` decimal(18,2) DEFAULT NULL,
  `pieces_justificatives` longtext DEFAULT '[]' COMMENT 'JSON [{ref_piece, description}]',
  `validation_status` varchar(20) NOT NULL DEFAULT 'draft',
  `validation_note` text DEFAULT NULL,
  `fait_par` varchar(255) DEFAULT NULL,
  `revue_par` varchar(255) DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `ia_result` longtext DEFAULT NULL,
  `ia_score` decimal(4,1) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_foci_mission` (`mission_id`),
  KEY `idx_foci_assignment` (`assignment_id`),
  KEY `idx_foci_fiche_test` (`fiche_test_id`),
  KEY `idx_foci_test_ref` (`test_ref`),
  KEY `idx_foci_obj` (`obj_num`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Fiche d''Observation CI (FOCI) — document séparé de l''Outil XIV';

