-- Listage de la structure de table fruitiva. fiche_test_outils
CREATE TABLE IF NOT EXISTS `fiche_test_outils` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `fiche_test_id` bigint(20) unsigned NOT NULL COMMENT 'FK mission_phase_fiche_test.id',
  `mission_id` bigint(20) unsigned NOT NULL,
  `assignment_id` bigint(20) unsigned NOT NULL,
  `procedure_code` varchar(80) NOT NULL COMMENT 'Code procédure programme de travail ex: T1.1',
  `test_ref` varchar(80) NOT NULL COMMENT 'Référence test ex: T1.1::0',
  `proc_idx` smallint(6) NOT NULL DEFAULT 0,
  `obj_num` varchar(20) DEFAULT NULL,
  `outil_code` varchar(5) NOT NULL COMMENT 'I II III … XV',
  `outil_table` varchar(80) NOT NULL,
  `outil_id` bigint(20) unsigned NOT NULL,
  `version` smallint(5) unsigned NOT NULL DEFAULT 1,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `ia_suggestion` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`ia_suggestion`)),
  `ia_score` decimal(4,1) DEFAULT NULL,
  `ia_generated_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_fto_fiche` (`fiche_test_id`),
  KEY `idx_fto_proc` (`procedure_code`,`test_ref`),
  KEY `idx_fto_outil` (`outil_code`,`outil_id`),
  KEY `idx_fto_current` (`fiche_test_id`,`is_current`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

