  KEY `idx_date_end` (`date_end`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_type_active` (`type`,`is_active`),
  KEY `idx_date_range` (`date_start`,`date_end`),
  CONSTRAINT `global_unavailabilities_ibfk_1` FOREIGN KEY (`type`) REFERENCES `unavailability_types` (`code`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

