-- Listage de la structure de table fruitiva. ia_propositions
CREATE TABLE IF NOT EXISTS `ia_propositions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `item_id` bigint(20) unsigned NOT NULL,
  `contenu` text NOT NULL,
  `type` enum('amelioration','validation','alerte') NOT NULL DEFAULT 'amelioration',
  `priorite` enum('haute','moyenne','faible') NOT NULL DEFAULT 'moyenne',
  `actions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of action strings' CHECK (json_valid(`actions`)),
  `indicateurs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of KPI strings' CHECK (json_valid(`indicateurs`)),
  `echeance` varchar(50) DEFAULT NULL,
  `generated_by` varchar(100) NOT NULL DEFAULT 'claude',
  `generated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `is_accepted` tinyint(1) DEFAULT NULL COMMENT 'NULL=en attente, TRUE=accepté, FALSE=rejeté',
  `accepted_by` bigint(20) unsigned DEFAULT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_prop_accepted` (`accepted_by`),
  KEY `idx_prop_item` (`item_id`),
  KEY `idx_prop_type` (`type`),
  KEY `idx_prop_priorite` (`priorite`),
  KEY `idx_prop_accepted` (`is_accepted`),
  CONSTRAINT `fk_prop_accepted` FOREIGN KEY (`accepted_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_prop_item` FOREIGN KEY (`item_id`) REFERENCES `analyse_conformite_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

