  `synthese_executive` text DEFAULT NULL,
  `points_forts` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`points_forts`)),
  `axes_amelioration` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`axes_amelioration`)),
  `risques_critiques` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`risques_critiques`)),
  `plan_action` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`plan_action`)),
  `prochaine_etape` text DEFAULT NULL,
  `score_au_moment` decimal(5,2) DEFAULT NULL,
  `generated_by` varchar(100) NOT NULL DEFAULT 'claude',
  `generated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_synthese_ac` (`analyse_conformite_id`),
  CONSTRAINT `fk_synthese_ac` FOREIGN KEY (`analyse_conformite_id`) REFERENCES `analyse_conformites` (`id`) ON DELETE CASCADE
