-- Listage de la structure de table fruitiva. missions
CREATE TABLE IF NOT EXISTS `missions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(30) DEFAULT NULL,
  `fpm_number` varchar(20) DEFAULT NULL,
  `audit_exercise_id` bigint(20) unsigned NOT NULL,
  `entity_id` bigint(20) unsigned DEFAULT NULL,
  `mission_type_id` bigint(20) unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `libelle` varchar(255) DEFAULT NULL,
  `objective` text DEFAULT NULL,
  `domain` varchar(120) DEFAULT NULL,
  `description` bigint(20) unsigned DEFAULT NULL,
  `reference_document` varchar(120) DEFAULT NULL,
  `priority` enum('basse','moyenne','haute','critique') NOT NULL DEFAULT 'moyenne',
  `planned_start_date` date DEFAULT NULL,
  `planned_end_date` date DEFAULT NULL,
  `planned_duration_days` int(11) NOT NULL DEFAULT 0,
  `status` enum('brouillon','planifiée','en_cours','terminée','annulée') NOT NULL DEFAULT 'brouillon',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `missions_audit_exercise_id_status_index` (`audit_exercise_id`,`status`),
  KEY `missions_mission_type_id_status_index` (`mission_type_id`,`status`),
  KEY `missions_code_index` (`code`),
  KEY `missions_fpm_number_index` (`fpm_number`),
  KEY `missions_created_by_foreign` (`created_by`),
  KEY `missions_updated_by_foreign` (`updated_by`),
  CONSTRAINT `missions_audit_exercise_id_foreign` FOREIGN KEY (`audit_exercise_id`) REFERENCES `audit_exercises` (`id`),
  CONSTRAINT `missions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `missions_mission_type_id_foreign` FOREIGN KEY (`mission_type_id`) REFERENCES `mission_types` (`id`),
  CONSTRAINT `missions_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

