-- Listage de la structure de table fruitiva. mission_auditeur_budgets
CREATE TABLE IF NOT EXISTS `mission_auditeur_budgets` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `affectation_id` bigint(20) unsigned NOT NULL,
  `mission_id` bigint(20) unsigned NOT NULL,
  `auditeur_id` bigint(20) unsigned NOT NULL,
  `montant` decimal(15,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_auditeur_affectation` (`affectation_id`),
  KEY `idx_mission_id` (`mission_id`),
  KEY `idx_auditeur_id` (`auditeur_id`),
  CONSTRAINT `mission_auditeur_budgets_ibfk_1` FOREIGN KEY (`affectation_id`) REFERENCES `mission_phase_auditeurs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mission_auditeur_budgets_ibfk_2` FOREIGN KEY (`mission_id`) REFERENCES `mission_programmation` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mission_auditeur_budgets_ibfk_3` FOREIGN KEY (`auditeur_id`) REFERENCES `auditors` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

