  `entity_id` bigint(20) unsigned DEFAULT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `custom_label` varchar(255) DEFAULT NULL,
  `montant` decimal(15,2) NOT NULL DEFAULT 0.00,
