  CONSTRAINT `fk_mabl_mission` FOREIGN KEY (`mission_id`) REFERENCES `mission_programmation` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

