-- Listage de la structure de table fruitiva. mission_audit_affectations
CREATE TABLE IF NOT EXISTS `mission_audit_affectations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mission_programmation_id` bigint(20) unsigned NOT NULL,
  `mission_type_id` bigint(20) unsigned DEFAULT NULL,
  `audit_type_code` varchar(10) NOT NULL COMMENT 'AC|AF|AP|AM|RP|ES',
  `audit_form_id` bigint(20) unsigned NOT NULL COMMENT '→ ddmparam.audit_type_forms.id',
  `form_code` varchar(160) DEFAULT NULL,
  `form_label` varchar(300) DEFAULT NULL,
  `form_url_path` varchar(400) DEFAULT NULL,
  `form_icon` varchar(100) DEFAULT NULL,
  `phase_num` tinyint(3) unsigned DEFAULT NULL,
  `phase_label` varchar(100) DEFAULT NULL,
  `parent_form_id` bigint(20) unsigned DEFAULT NULL,
  `status` enum('pending','in_progress','completed','skipped','blocked') NOT NULL DEFAULT 'pending',
  `planned_start` date DEFAULT NULL,
  `planned_end` date DEFAULT NULL,
  `is_mandatory` tinyint(1) NOT NULL DEFAULT 0,
  `notes` text DEFAULT NULL,
  `created_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_maa_prog_form` (`mission_programmation_id`,`audit_form_id`),
  KEY `idx_maa_type` (`audit_type_code`),
  KEY `idx_maa_phase` (`phase_num`),
  KEY `idx_maa_status` (`status`),
  KEY `idx_maa_deleted` (`deleted_at`),
  CONSTRAINT `fk_maa_mission` FOREIGN KEY (`mission_programmation_id`) REFERENCES `mission_programmation` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='1 ligne par formulaire × mission. Dates et statut globaux (identiques toutes entités).';

-- Listage des données de la table fruitiva.mission_audit_affectations : ~0 rows (environ)

-- Listage de la structure de table fruitiva. mission_audit_affectation_auditeurs
CREATE TABLE IF NOT EXISTS `mission_audit_affectation_auditeurs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `affectation_id` bigint(20) unsigned NOT NULL COMMENT '→ mission_audit_affectations.id',
  `entity_id` bigint(20) unsigned NOT NULL COMMENT '→ entities.id',
  `auditeur_id` bigint(20) unsigned NOT NULL COMMENT '→ auditors.id',
  `role_code` varchar(10) DEFAULT NULL COMMENT 'DM|CM|AS|AJ',
  `role_id` bigint(20) unsigned DEFAULT NULL,
  `role_label` varchar(100) DEFAULT NULL,
  `parent_auditeur_id` bigint(20) unsigned DEFAULT NULL,
  `is_lead` tinyint(1) NOT NULL DEFAULT 0,
  `date_affectation` date DEFAULT NULL,
  `affecte_par` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_maaa_aff_entity_aud` (`affectation_id`,`entity_id`,`auditeur_id`),
  KEY `idx_maaa_affectation` (`affectation_id`),
  KEY `idx_maaa_entity` (`entity_id`),
  KEY `idx_maaa_auditeur` (`auditeur_id`),
  CONSTRAINT `fk_maaa_affectation` FOREIGN KEY (`affectation_id`) REFERENCES `mission_audit_affectations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_maaa_auditeur` FOREIGN KEY (`auditeur_id`) REFERENCES `auditors` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_maaa_entity` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Auditeurs par formulaire × entité. Même formulaire = auditeurs différents par entité.';

