  CONSTRAINT `mission_budgets_ibfk_1` FOREIGN KEY (`mission_id`) REFERENCES `mission_programmation` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mission_budgets_ibfk_2` FOREIGN KEY (`budget_type_id`) REFERENCES `budget_types` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

