-- Listage de la structure de table fruitiva. mission_phase_amq
CREATE TABLE IF NOT EXISTS `mission_phase_amq` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `assignment_id` bigint(20) unsigned NOT NULL,
  `mission_id` bigint(20) unsigned NOT NULL,
  `code` varchar(50) NOT NULL,
  `intitule_qem` varchar(500) DEFAULT NULL COMMENT 'Intitulé du questionnaire d''évaluation des marchés',
  `fait_par` varchar(255) DEFAULT NULL,
  `revue_par` varchar(255) DEFAULT NULL,
  `date_fait` date DEFAULT NULL,
  `date_revue` date DEFAULT NULL,
  `commentaire_global` text DEFAULT NULL,
  `validation_status` varchar(30) NOT NULL DEFAULT 'draft' COMMENT 'draft | in_review | validated',
  `validation_note` text DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` datetime DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_amq_assignment` (`assignment_id`),
  UNIQUE KEY `uq_amq_code` (`code`),
  KEY `idx_amq_mission` (`mission_id`),
  KEY `idx_amq_status` (`validation_status`),
  KEY `idx_amq_mission_status` (`mission_id`,`validation_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Formulaire principal AMQ — Questionnaire d''Évaluation des Marchés';

