-- Listage de la structure de table fruitiva. mission_phase_ap
CREATE TABLE IF NOT EXISTS `mission_phase_ap` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `assignment_id` bigint(20) unsigned NOT NULL,
  `mission_id` bigint(20) unsigned NOT NULL,
  `processus` longtext DEFAULT '[]' COMMENT 'JSON [{code, libelle, type, responsable, description, entrees, sorties, risques}]',
  `acteurs` longtext DEFAULT '[]' COMMENT 'JSON [{nom, fonction, role_dans_processus}]',
  `flux` longtext DEFAULT '[]' COMMENT 'JSON [{de, vers, nature, support}]',
  `observations` longtext DEFAULT '[]' COMMENT 'JSON [{processus_code, observation, niveau_criticite}]',
  `synthese` longtext DEFAULT NULL,
  `bpmn_annotations` longtext DEFAULT NULL COMMENT 'Copies BPMN annotées par l''auditeur — JSON { "process_id": "<bpmn:definitions…/>" }. Le BPMN officiel (bpmn_diagrams) n''est jamais modifié.',
  `fait_par` varchar(255) DEFAULT NULL,
  `revue_par` varchar(255) DEFAULT NULL,
  `validation_status` varchar(20) NOT NULL DEFAULT 'draft',
  `submitted_at` timestamp NULL DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `validation_note` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ap_assignment` (`assignment_id`),
  KEY `idx_ap_mission` (`mission_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AC P3.1 — Analyse des processus';

