-- Listage de la structure de table fruitiva. mission_phase_apci
CREATE TABLE IF NOT EXISTS `mission_phase_apci` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `assignment_id` bigint(20) unsigned NOT NULL,
  `mission_id` bigint(20) unsigned NOT NULL,
  `processus_identifies` longtext DEFAULT '[]' COMMENT 'JSON [{code, libelle, responsable, criticite}]',
  `risques_identifies` longtext DEFAULT '[]' COMMENT 'JSON [{processus_code, description, probabilite, impact, niveau}]',
  `points_forts_ci` longtext DEFAULT '[]' COMMENT 'JSON [{description, processus_concerne}]',
  `points_faibles_ci` longtext DEFAULT '[]' COMMENT 'JSON [{description, processus_concerne, recommandation}]',
  `recommandations_prelim` longtext DEFAULT '[]' COMMENT 'JSON [{description, priorite}]',
  `synthese` longtext DEFAULT NULL,
  `date_analyse` date DEFAULT NULL,
  `fait_par` varchar(255) DEFAULT NULL,
  `revue_par` varchar(255) DEFAULT NULL,
  `validation_status` varchar(20) NOT NULL DEFAULT 'draft',
  `submitted_at` timestamp NULL DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `validation_note` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_apci_assignment` (`assignment_id`),
  KEY `idx_apci_mission` (`mission_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AC P3 — Analyse processus et contrôles internes (parent)';

