-- Listage de la structure de table fruitiva. mission_phase_apt
CREATE TABLE IF NOT EXISTS `mission_phase_apt` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mission_id` bigint(20) unsigned NOT NULL,
  `assignment_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `code` varchar(60) NOT NULL,
  `validation_status` enum('draft','in_review','validated','rejected') NOT NULL DEFAULT 'draft',
  `ref_procedure` varchar(120) DEFAULT NULL,
  `version_vigueur` varchar(60) DEFAULT NULL,
  `intitule_proc` varchar(500) DEFAULT NULL,
  `service_dept` varchar(200) DEFAULT NULL,
  `responsable_proc` varchar(200) DEFAULT NULL,
  `date_entree_vigueur` date DEFAULT NULL,
  `date_derniere_revision` date DEFAULT NULL,
  `description_proc` longtext DEFAULT NULL,
  `population_totale` int(11) DEFAULT NULL,
  `taille_echantillon` int(11) DEFAULT NULL,
  `methode_echantillonnage` varchar(60) DEFAULT NULL,
  `items_matrice` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`items_matrice`)),
  `plan_collecte` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`plan_collecte`)),
  `grille_entretien` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`grille_entretien`)),
  `synthese_ff` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`synthese_ff`)),
  `niveau_conformite` varchar(30) DEFAULT NULL,
  `niveau_risque` varchar(20) DEFAULT NULL,
  `fiabilite_controle` varchar(20) DEFAULT NULL,
  `suites` varchar(30) DEFAULT NULL,
  `commentaire_global` longtext DEFAULT NULL,
  `fait_par` varchar(255) DEFAULT NULL,
  `date_fait` date DEFAULT NULL,
  `revue_par` varchar(255) DEFAULT NULL,
  `date_revue` date DEFAULT NULL,
  `approuve_par` varchar(255) DEFAULT NULL,
  `date_approbation` date DEFAULT NULL,
  `flowchart_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`flowchart_data`)),
  `attached_files` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`attached_files`)),
  `submitted_at` timestamp NULL DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `validation_note` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_apt_code` (`code`),
  KEY `idx_apt_mission` (`mission_id`),
  KEY `idx_apt_status` (`validation_status`),
  KEY `idx_apt_created_by` (`created_by`)
