-- Listage de la structure de table fruitiva. mission_phase_assignments
CREATE TABLE IF NOT EXISTS `mission_phase_assignments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mission_programmation_id` bigint(20) unsigned NOT NULL,
  `mission_phase_id` bigint(20) unsigned NOT NULL,
  `entity_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK → entities.id | NULL = toutes entités | SET = entité spécifique',
  `status` varchar(50) NOT NULL DEFAULT 'pending' COMMENT 'pending | in_progress | completed | skipped',
  `owner_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Auditeur responsable de la phase',
  `planned_start` date DEFAULT NULL,
  `planned_end` date DEFAULT NULL,
  `actual_start` date DEFAULT NULL,
  `actual_end` date DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL COMMENT 'Date de soumission pour validation',
  `submitted_by` bigint(20) unsigned DEFAULT NULL COMMENT 'FK auditors.id — qui a soumis',
  `validated_at` timestamp NULL DEFAULT NULL COMMENT 'Date de validation finale DM',
  `validated_by` bigint(20) unsigned DEFAULT NULL COMMENT 'FK auditors.id — DM validateur',
  `validation_status` varchar(30) NOT NULL DEFAULT 'draft' COMMENT 'draft | submitted | validated | rejected',
  `validation_note` text DEFAULT NULL COMMENT 'Note de rejet/validation du DM',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mpa_prog_phase_entity` (`mission_programmation_id`,`mission_phase_id`,`entity_id`),
  UNIQUE KEY `uq_mp_assignment` (`mission_programmation_id`,`mission_phase_id`,`entity_id`),
  KEY `fk_mp_assignments_phase` (`mission_phase_id`),
  KEY `fk_mp_assignments_owner` (`owner_id`),
  KEY `idx_mpa_entity` (`entity_id`),
  KEY `idx_mpa_status` (`status`),
  KEY `idx_mpa_phase` (`mission_phase_id`),
  KEY `idx_val_status` (`validation_status`),
  KEY `idx_submitted_by` (`submitted_by`),
  KEY `idx_validated_by` (`validated_by`),
  KEY `idx_mpa_val_status` (`validation_status`),
  KEY `idx_mpa_submitted` (`submitted_by`),
  KEY `idx_mpa_validated` (`validated_by`),
  KEY `idx_mpa_mission_status` (`mission_programmation_id`,`status`),
  CONSTRAINT `fk_mpa_mission_phase` FOREIGN KEY (`mission_phase_id`) REFERENCES `mission_phases` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

