-- Listage de la structure de table fruitiva. mission_phase_at
CREATE TABLE IF NOT EXISTS `mission_phase_at` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mission_id` bigint(20) unsigned NOT NULL COMMENT 'FK mission_programmation.id',
  `assignment_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK mission_phase_assignments.id',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `code` varchar(60) NOT NULL,
  `validation_status` enum('draft','in_review','validated','rejected') NOT NULL DEFAULT 'draft',
  `raci_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`raci_data`)),
  `functions_added` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`functions_added`)),
  `synthese` longtext DEFAULT NULL COMMENT 'Synthèse/observations globales',
  `fait_par` varchar(255) DEFAULT NULL,
  `revue_par` varchar(255) DEFAULT NULL,
  `date_fait` date DEFAULT NULL,
  `date_revue` date DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `validation_note` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_mat_mission` (`mission_id`),
  KEY `idx_mat_assignment` (`assignment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Formulaire Analyse des Tâches - Matrice RACI par mission';

-- Listage des données de la table fruitiva.mission_phase_at : ~0 rows (environ)

-- Listage de la structure de table fruitiva. mission_phase_auditeurs
CREATE TABLE IF NOT EXISTS `mission_phase_auditeurs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mission_id` bigint(20) unsigned NOT NULL,
  `phase_id` bigint(20) unsigned NOT NULL,
  `auditeur_id` bigint(20) unsigned NOT NULL,
  `role_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Référence vers mission_roles',
  `role` varchar(50) DEFAULT NULL COMMENT 'Code du rôle (DM, CM, AS, AJ) - redondant pour affichage rapide',
  `parent_auditeur_id` bigint(20) unsigned DEFAULT NULL COMMENT 'ID de l''auditeur superviseur (hiérarchie)',
  `entites` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`entites`)),
  `date_affectation` date NOT NULL,
  `affecte_par` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mpa` (`mission_id`,`phase_id`,`auditeur_id`),
  KEY `idx_mpa_phase` (`phase_id`),
  KEY `idx_mpa_auditeur` (`auditeur_id`),
  KEY `idx_mpa_role` (`role_id`),
  KEY `idx_mpa_parent` (`parent_auditeur_id`),
  CONSTRAINT `mission_phase_auditeurs_ibfk_1` FOREIGN KEY (`mission_id`) REFERENCES `mission_programmation` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mission_phase_auditeurs_ibfk_2` FOREIGN KEY (`phase_id`) REFERENCES `mission_codephases` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mission_phase_auditeurs_ibfk_3` FOREIGN KEY (`auditeur_id`) REFERENCES `auditors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mission_phase_auditeurs_ibfk_4` FOREIGN KEY (`role_id`) REFERENCES `mission_roles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `mission_phase_auditeurs_ibfk_5` FOREIGN KEY (`parent_auditeur_id`) REFERENCES `auditors` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

