-- Listage de la structure de table fruitiva. mission_phase_auditors
CREATE TABLE IF NOT EXISTS `mission_phase_auditors` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mission_id` bigint(20) unsigned NOT NULL COMMENT 'ID de la mission',
  `mission_phase_id` bigint(20) unsigned NOT NULL COMMENT 'ID de la phase',
  `auditor_id` bigint(20) unsigned NOT NULL COMMENT 'ID de l''auditeur',
  `auditor_role` enum('DM','CM','JUNIOR','SENIOR') NOT NULL COMMENT 'Rôle: Directeur Mission, Chef Mission, Junior, Senior',
  `assigned_by` bigint(20) unsigned DEFAULT NULL COMMENT 'ID du user qui a assigné',
  `assigned_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_mission_phase_auditor` (`mission_id`,`mission_phase_id`,`auditor_id`),
  KEY `idx_mission_phase` (`mission_id`,`mission_phase_id`),
  KEY `idx_auditor` (`auditor_id`),
  KEY `idx_role` (`auditor_role`),
  KEY `fk_mpa_phase` (`mission_phase_id`),
  CONSTRAINT `fk_mpa_auditor` FOREIGN KEY (`auditor_id`) REFERENCES `auditors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mpa_mission` FOREIGN KEY (`mission_id`) REFERENCES `audit_missions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_mpa_phase` FOREIGN KEY (`mission_phase_id`) REFERENCES `mission_phases` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

