-- Listage de la structure de table fruitiva. mission_phase_chat
CREATE TABLE IF NOT EXISTS `mission_phase_chat` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `assignment_id` bigint(20) unsigned NOT NULL COMMENT 'FK mission_phase_assignments.id',
  `mission_id` bigint(20) unsigned NOT NULL COMMENT 'FK mission_programmation.id',
  `phase_type` varchar(30) DEFAULT NULL,
  `form_code` varchar(160) DEFAULT NULL COMMENT 'Rattaché à un formulaire précis (null=phase générale)',
  `author_id` bigint(20) unsigned NOT NULL COMMENT 'FK auditors.id',
  `author_role` varchar(10) NOT NULL COMMENT 'DM|CM|AS|AJ',
  `parent_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Réponse à un message',
  `content` text NOT NULL,
  `type` varchar(30) NOT NULL DEFAULT 'message' COMMENT 'message | instruction | correction | validation | rejet | info',
  `priority` varchar(20) NOT NULL DEFAULT 'normal' COMMENT 'normal | urgent | bloquant',
  `is_pinned` tinyint(1) NOT NULL DEFAULT 0,
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `read_at` timestamp NULL DEFAULT NULL,
  `attachments` text DEFAULT NULL COMMENT 'JSON array de fichiers attachés',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_chat_assignment` (`assignment_id`),
  KEY `idx_chat_mission` (`mission_id`),
  KEY `idx_chat_form` (`form_code`),
  KEY `idx_chat_author` (`author_id`),
  KEY `idx_chat_parent` (`parent_id`),
  KEY `idx_chat_unread` (`is_read`,`assignment_id`),
  KEY `mpc_mission_type_idx` (`mission_id`,`phase_type`),
  CONSTRAINT `fk_chat_parent` FOREIGN KEY (`parent_id`) REFERENCES `mission_phase_chat` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Chat intégré par phase/formulaire avec hiérarchie DM>CM>AS>AJ';

