-- Listage de la structure de table fruitiva. mission_phase_fiche_constat
CREATE TABLE IF NOT EXISTS `mission_phase_fiche_constat` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `num_frap` varchar(30) DEFAULT NULL COMMENT 'N° FRAP affiché (ex: FRAP-QCI-001)',
  `test_ref` varchar(80) DEFAULT NULL COMMENT 'Référence du test (ex: T_O1)',
  `obj_num` varchar(20) DEFAULT NULL COMMENT 'N° objectif (ex: O1)',
  `assignment_id` bigint(20) unsigned NOT NULL,
  `mission_id` bigint(20) unsigned NOT NULL,
  `ref_constat` varchar(50) DEFAULT NULL,
  `axe_audit` varchar(255) DEFAULT NULL,
  `objectif_controle` varchar(255) DEFAULT NULL COMMENT 'Objectif de contrôle (regroupement)',
  `rubrique` varchar(255) DEFAULT NULL COMMENT 'Rubrique (ex: Protection du patrimoine)',
  `sous_rubrique` varchar(255) DEFAULT NULL COMMENT 'Sous-rubrique (si existant)',
  `fait` longtext NOT NULL,
  `probleme` text DEFAULT NULL COMMENT 'Libellé du problème',
  `critere` longtext DEFAULT NULL,
  `cause` longtext DEFAULT NULL,
  `impact` longtext DEFAULT NULL,
  `impact_financier` decimal(18,2) DEFAULT NULL,
  `importance` varchar(20) DEFAULT 'moyenne' COMMENT 'elevee|moyenne|faible',
  `niveau_maitrise` varchar(30) DEFAULT NULL COMMENT '1_faible..5_excellent',
  `niveau_controle` varchar(30) DEFAULT NULL COMMENT 'Déduit automatiquement depuis niveau_maitrise',
