INSERT INTO `mission_phase_prog_ci` (`id`, `code`, `assignment_id`, `lignes`, `synthese`, `mission_id`, `diligences`, `tests_prevus`, `responsables`, `observations`, `fait_par`, `revue_par`, `validation_status`, `submitted_at`, `submitted_by`, `validated_at`, `validated_by`, `validation_note`, `created_by`, `created_at`, `updated_at`) VALUES
	(2, 'PTCI-ADI002-001', 68, '[{"num":"O1","objectif":"Vérifier : Faiblesse analyse processus","ref_rci":"FI-001","tests":[{"ref":"T_O1","libelle":"Vérifier la conformité des procédures de réception et contrôle qualité des matières premières agricoles","procedures":["Examiner les registres de réception pour confirmer l\'enregistrement systématique des lots de matières premières","Contrôler la traçabilité des échantillons prélevés en comparant les données du registre avec les étiquettes des échantillons","Vérifier la cohérence entre les critères de qualité définis dans le manuel qualité et les résultats des analyses réalisées","Analyser les écarts entre les normes internes et les résultats des contrôles pour identifier les risques de non-conformité","S\'assurer que les actions correctives sont documentées et mises en œuvre en cas de détection de non-conformités"],"auditeur":"IMOROU nawal","date_debut":"","date_fin":"","lieu":"","taille_echantillon":"","periode_testee":""}],"_source":"RADO+RCI/FI-001","_rado_id":1,"_rci_id":1,"_axe_rado":"Optimisation des processus agricoles","_priorite":"haute","_indicateurs":"","_criteres_eval":"Les processus sont documentés, analysés et optimisés selon les normes ISO 9001 ou équivalentes. Les écarts identifiés doivent faire l\'objet de plans d\'action correctifs mesurables avec des responsables désignés et des échéances claires. L\'efficacité des analyses est évaluée via des indicateurs de performance (ex : rendement, qualité, délais) comparés aux benchmarks sectoriels ou aux objectifs internes de FRUCTIVA AGRO 1","_risque_code":"FI-001","_risque_libelle":"Cyberattaque ou intrusion","_process_name":"Réception & contrôle qualité matières","_objectif_operationnel":"Obj. Opérationnel 1","_description_controle":"Mise en place d’un contrôle visant à suivre, analyser et valider les volumes de production agricole afin de garantir l’atteinte des objectifs de rendement fixés.\\n","_preuve_controle":"","_type_controle":"Préventif","_criticite":2,"_responsable":"CHEF SERVICE TRANSPORT"},{"num":"O2","objectif":"Vérifier : Faiblese analyses des preocessus","ref_rci":"ST-001","tests":[{"ref":"T_O2","libelle":"Vérifier l\'efficacité des contrôles qualité sur les matières premières agricoles à réception","procedures":["Examiner les registres de réception des matières premières (fruits, légumes) pour vérifier la présence des contrôles systématiques","Contrôler les fiches de contrôle qualité (poids, taille, état sanitaire) pour s\'assurer de leur conformité aux normes internes","Observer les procédures de prélèvement d\'échantillons aléatoires pour valider leur représentativité","Vérifier l\'enregistrement des non-conformités et leur traitement (rejet, retour, traitement spécifique)","Analyser les indicateurs de qualité (taux de rejet, retards de livraison) pour identifier les tendances et axes d\'amélioration"],"auditeur":"IMOROU nawal","date_debut":"","date_fin":"","lieu":"","taille_echantillon":"","periode_testee":""}],"_source":"RADO+RCI/ST-001","_rado_id":1,"_rci_id":1,"_axe_rado":"Optimisation des processus agricoles","_priorite":"haute","_indicateurs":"","_criteres_eval":"Les processus sont documentés, analysés et optimisés selon les normes ISO 9001 ou équivalentes. Les écarts identifiés doivent faire l\'objet de plans d\'action correctifs mesurables avec des responsables désignés et des échéances claires. L\'efficacité des analyses est évaluée via des indicateurs de performance (ex : rendement, qualité, délais) comparés aux benchmarks sectoriels ou aux objectifs internes de FRUCTIVA AGRO 1","_risque_code":"ST-001","_risque_libelle":"Panne du système d\'information","_process_name":"Réception & contrôle qualité matières","_objectif_operationnel":"Obj. Opérationnel 1","_description_controle":"Contrôle visant à s’assurer de l’application effective des techniques agricoles modernes (irrigation, fertilisation, méthodes écologiques) par les producteurs.","_preuve_controle":"QC 11","_type_controle":"Détectif","_criticite":16,"_responsable":"DIRECTEUR COMMERCIALE ET MARQUETING"},{"num":"O3","objectif":"Vérifier : Faiblesse analyse processus 1","ref_rci":"FI-001","tests":[{"ref":"T_O3","libelle":"Vérifier la conformité des procédures de réception et de contrôle qualité des matières premières agricoles","procedures":["Examiner les registres de réception pour confirmer l\'enregistrement systématique des lots de matières premières","Contrôler la traçabilité des documents de contrôle qualité (certificats, analyses microbiologiques, résidus de pesticides)","Vérifier la cohérence entre les spécifications techniques des fournisseurs et les résultats des contrôles internes","Analyser les écarts entre les non-conformités détectées et les actions correctives mises en place","S\'assurer que les responsables qualité appliquent les critères d\'acceptation/rejet définis dans le référentiel"],"auditeur":"","date_debut":"","date_fin":"","lieu":"","taille_echantillon":"","periode_testee":""}],"_source":"RADO+RCI/FI-001","_rado_id":1,"_rci_id":1,"_axe_rado":"Optimisation des processus agricoles","_priorite":"haute","_indicateurs":"","_criteres_eval":"Les processus sont documentés, analysés et optimisés selon les normes ISO 9001 ou équivalentes. Les écarts identifiés doivent faire l\'objet de plans d\'action correctifs mesurables avec des responsables désignés et des échéances claires. L\'efficacité des analyses est évaluée via des indicateurs de performance (ex : rendement, qualité, délais) comparés aux benchmarks sectoriels ou aux objectifs internes de FRUCTIVA AGRO 1","_risque_code":"FI-001","_risque_libelle":"Cyberattaque ou intrusion","_process_name":"Réception & contrôle qualité matières","_objectif_operationnel":"Obj. Opérationnel 1","_description_controle":"Mise en place d’un contrôle visant à suivre, analyser et valider les volumes de production agricole afin de garantir l’atteinte des objectifs de rendement fixés.\\n","_preuve_controle":"","_type_controle":"Préventif","_criticite":2,"_responsable":"CHEF SERVICE TRANSPORT"},{"num":"O4","objectif":"OBJ2","ref_rci":"FI-001","tests":[{"ref":"T_O4","libelle":"Vérifier la conformité des certificats d\'analyse des matières premières à l\'arrivée","procedures":["Consulter les registres de réception pour identifier les lots de matières premières livrés","Vérifier la présence et la validité des certificats d\'analyse (CA) pour chaque lot","Comparer les résultats des CA avec les spécifications techniques de FRUITIVA","Documenter les écarts éventuels et alerter le responsable qualité si nécessaire","Archiver les CA conformes dans le système de gestion documentaire"],"auditeur":"","date_debut":"","date_fin":"","lieu":"","taille_echantillon":"","periode_testee":""}],"_source":"RADO+RCI/FI-001","_rado_id":1,"_rci_id":1,"_axe_rado":"Optimisation des processus agricoles","_priorite":"haute","_indicateurs":"","_criteres_eval":"L\'axe est évalué sur la base de la conformité des processus aux standards définis, de l\'efficacité opérationnelle mesurée par les indicateurs de performance clés, et de la pertinence des analyses réalisées pour identifier les faiblesses. Les écarts identifiés doivent être documentés et priorisés selon leur impact sur la performance globale de l\'entité.","_risque_code":"FI-001","_risque_libelle":"Cyberattaque ou intrusion","_process_name":"Réception & contrôle qualité matières","_objectif_operationnel":"Obj. Opérationnel 1","_description_controle":"Mise en place d’un contrôle visant à suivre, analyser et valider les volumes de production agricole afin de garantir l’atteinte des objectifs de rendement fixés.\\n","_preuve_controle":"","_type_controle":"Préventif","_criticite":2,"_responsable":"CHEF SERVICE TRANSPORT"},{"num":"O5","objectif":"Vérifier : Faiblease analyse processus 1","ref_rci":"FI-001","tests":[{"ref":"T_O5","libelle":"Vérifier la conformité des contrôles qualité à l\'arrivée des matières premières agricoles","procedures":["Examiner les registres de réception pour confirmer l\'enregistrement systématique des lots de matières premières","Vérifier la présence et la validité des certificats d\'analyse (COA) pour chaque lot reçu","Contrôler la traçabilité des échantillons prélevés et leur conservation selon les normes HACCP","Analyser les écarts entre les spécifications contractuelles et les résultats des contrôles qualité","S\'assurer que les actions correctives sont documentées et appliquées en cas de non-conformité"],"auditeur":"","date_debut":"","date_fin":"","lieu":"","taille_echantillon":"","periode_testee":""}],"_source":"RADO+RCI/FI-001","_rado_id":1,"_rci_id":1,"_axe_rado":"Optimisation des processus agricoles","_priorite":"haute","_indicateurs":"","_criteres_eval":"L\'axe est évalué sur la base de la conformité des processus aux standards définis, de l\'efficacité opérationnelle mesurée par les indicateurs de performance clés, et de la pertinence des analyses réalisées pour identifier les faiblesses. Les écarts identifiés doivent être documentés et priorisés selon leur impact sur la performance globale de l\'entité.","_risque_code":"FI-001","_risque_libelle":"Cyberattaque ou intrusion","_process_name":"Réception & contrôle qualité matières","_objectif_operationnel":"Obj. Opérationnel 1","_description_controle":"Mise en place d’un contrôle visant à suivre, analyser et valider les volumes de production agricole afin de garantir l’atteinte des objectifs de rendement fixés.\\n","_preuve_controle":"","_type_controle":"Préventif","_criticite":2,"_responsable":"CHEF SERVICE TRANSPORT"}]', NULL, 47, '[]', '[]', '[]', NULL, NULL, NULL, 'draft', NULL, NULL, NULL, NULL, NULL, 10, '2026-04-08 10:31:45', '2026-04-20 10:13:14'),
