-- Listage de la structure de table fruitiva. mission_phase_reunion_lancement
CREATE TABLE IF NOT EXISTS `mission_phase_reunion_lancement` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL COMMENT 'Ex: FRL-2024-001',
  `assignment_id` bigint(20) unsigned NOT NULL,
  `mission_id` bigint(20) unsigned NOT NULL,
  `date_reunion` date DEFAULT NULL,
  `heure_debut` varchar(10) DEFAULT NULL,
  `heure_fin` varchar(10) DEFAULT NULL,
  `lieu` varchar(255) DEFAULT NULL,
  `presidente_par` varchar(255) DEFAULT NULL COMMENT 'Personne qui préside',
  `methodologie` text DEFAULT NULL COMMENT 'Section Méthodologie générale',
  `participants` longtext DEFAULT NULL COMMENT 'JSON : [{nom, prenom, fonction, entite, signature}]',
  `objectifs` longtext DEFAULT NULL COMMENT 'JSON : section 5 — objectifs + tests + observations',
  `preoccupations` longtext DEFAULT NULL COMMENT 'JSON : section 6 — préoccupations des audités',
  `signatures` longtext DEFAULT NULL COMMENT 'JSON : {chef_mission, representant_audites, auditeur_senior}',
  `media_items` longtext DEFAULT NULL,
  `documents_ref` longtext DEFAULT NULL,
  `fait_par` varchar(255) DEFAULT NULL,
  `revue_par` varchar(255) DEFAULT NULL,
  `validation_status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT 'draft | in_review | validated',
  `validation_note` text DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reunion_lancement_assignment` (`assignment_id`),
  KEY `idx_reunion_lancement_mission` (`mission_id`),
  KEY `idx_reunion_lancement_status` (`validation_status`),
  KEY `idx_reunion_lancement_date` (`date_reunion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PV Réunion de Lancement — Phase de Réalisation (FRL)';

