  `heure_debut` time DEFAULT NULL,
  `heure_fin` time DEFAULT NULL,
  `lieu` varchar(255) DEFAULT NULL,
  `ordre_du_jour` longtext DEFAULT '[]' COMMENT 'JSON [{point, responsable}]',
