  `description` text DEFAULT NULL,
  `parent_code` varchar(10) DEFAULT NULL COMMENT 'Code du rôle parent (hiérarchie)',
  `niveau` int(11) NOT NULL DEFAULT 0 COMMENT 'Niveau hiérarchique (0=DM, 1=CM, 2=AS, 3=AJ)',
  `max_enfants` int(11) DEFAULT NULL COMMENT 'Nombre max de subordonnés directs (NULL = illimité)',
  `ordre` int(11) NOT NULL DEFAULT 0 COMMENT 'Ordre d''affichage',
