-- Listage de la structure de table fruitiva. ordre_missions
CREATE TABLE IF NOT EXISTS `ordre_missions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reference_om` varchar(60) NOT NULL COMMENT 'Ex: OM-2026-001',
  `mission_prog_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Lien mission_programmation.id',
  `mission_id` bigint(20) unsigned DEFAULT NULL COMMENT 'Lien missions.id',
  `intitule` varchar(255) NOT NULL,
  `objectif` text DEFAULT NULL,
  `lieux` varchar(255) DEFAULT NULL,
  `domaine` varchar(100) DEFAULT NULL,
  `limite` text DEFAULT NULL COMMENT 'Périmètre / limites de la mission',
  `moyen` text DEFAULT NULL COMMENT 'Moyens alloués',
  `budget` decimal(18,2) NOT NULL DEFAULT 0.00,
  `date_debut` date DEFAULT NULL,
  `date_fin` date DEFAULT NULL,
  `duree` smallint(6) DEFAULT NULL,
  `phase` varchar(50) DEFAULT 'ORMI',
  `forme_diffusion` enum('electronique','papier','les_deux') NOT NULL DEFAULT 'electronique',
  `date_limite_diffusion` date DEFAULT NULL,
  `emetteur` varchar(150) DEFAULT NULL,
  `destinataire` varchar(255) DEFAULT NULL COMMENT 'Nom(s) destinataires principaux',
  `copie` text DEFAULT NULL COMMENT 'Destinataires en copie',
  `message_personnalise` text DEFAULT NULL COMMENT 'Message additionnel à inclure dans l''OM',
  `status` enum('brouillon','emis','envoye','accuse') NOT NULL DEFAULT 'brouillon',
  `pdf_path` varchar(500) DEFAULT NULL COMMENT 'Chemin storage du PDF généré',
  `envoye_le` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reference_om` (`reference_om`),
  KEY `idx_om_mission` (`mission_prog_id`),
  KEY `idx_om_status` (`status`),
  KEY `idx_om_date_debut` (`date_debut`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ordres de Mission émis par le service d''audit interne';

