-- Listage de la structure de table fruitiva. ordre_mission_auditeurs
CREATE TABLE IF NOT EXISTS `ordre_mission_auditeurs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `om_id` bigint(20) unsigned NOT NULL,
  `om_entite_id` bigint(20) unsigned DEFAULT NULL,
  `entity_id` bigint(20) unsigned DEFAULT NULL,
  `auditeur_id` bigint(20) unsigned NOT NULL,
  `role` varchar(50) DEFAULT NULL COMMENT 'DM, CM, AS, AJ …',
  `role_libelle` varchar(100) DEFAULT NULL,
  `ordre` tinyint(4) NOT NULL DEFAULT 0,
  `scope` enum('global','entite') NOT NULL DEFAULT 'global',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_om_auditeur` (`om_id`,`auditeur_id`),
  KEY `fk_oma_auditeur` (`auditeur_id`),
  KEY `idx_oma_scope` (`scope`),
  KEY `idx_oma_entity` (`entity_id`),
  KEY `idx_oma_entite_id` (`om_entite_id`),
  CONSTRAINT `fk_oma_auditeur` FOREIGN KEY (`auditeur_id`) REFERENCES `auditors` (`id`),
  CONSTRAINT `fk_oma_om` FOREIGN KEY (`om_id`) REFERENCES `ordre_missions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Auditeurs assignés à un Ordre de Mission';

