-- Listage de la structure de table fruitiva. ordre_mission_entites
CREATE TABLE IF NOT EXISTS `ordre_mission_entites` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `om_id` bigint(20) unsigned NOT NULL,
  `entity_id` bigint(20) unsigned NOT NULL,
  `email_contact` varchar(255) DEFAULT NULL COMMENT 'Email spécifique pour envoi de cet OM à cette entité',
  `nom_contact` varchar(150) DEFAULT NULL COMMENT 'Nom du responsable à l''entité',
  `date_debut` date DEFAULT NULL,
  `date_fin` date DEFAULT NULL,
  `duree` smallint(6) DEFAULT NULL,
  `lieux` varchar(255) DEFAULT NULL,
  `copie` varchar(500) DEFAULT NULL,
  `destinataire` varchar(255) DEFAULT NULL,
  `message` text DEFAULT NULL,
  `email_envoye` tinyint(1) NOT NULL DEFAULT 0,
  `email_envoye_le` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_om_entity` (`om_id`,`entity_id`),
  KEY `fk_ome_entity` (`entity_id`),
  CONSTRAINT `fk_ome_entity` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`),
  CONSTRAINT `fk_ome_om` FOREIGN KEY (`om_id`) REFERENCES `ordre_missions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Entités couvertes par un Ordre de Mission et leurs emails';

