  `mission_id` bigint(20) unsigned NOT NULL,
  `assignment_id` bigint(20) unsigned DEFAULT NULL,
  `procedure_code` varchar(80) DEFAULT NULL,
  `test_ref` varchar(80) DEFAULT NULL,
  `obj_num` varchar(20) DEFAULT NULL,
  `intitule` varchar(255) NOT NULL,
  `processus` varchar(255) DEFAULT NULL,
  `responsable` varchar(255) DEFAULT NULL,
  `date_analyse` date DEFAULT NULL,
  `observations` text DEFAULT NULL COMMENT 'Séparation des fonctions incompatibles',
