	(1, 'XII', 'outil_circularisation', 1, 3, 'O1', '{"date_envoi":null,"date_limite_reponse":null,"auditeur_responsable":"IMOROU nawal","demandes":[{"id":1,"fiche_id":1,"nom_tiers":"tiers 1","element_confirmer":"eeeeeee1","montant_periode":null,"date_envoi_demande":"2026-04-14","date_reponse":"2026-04-25","montant_envoye":"20000.00","montant_confirme":"100.00","element_confirme":"eeeeeee1","ecart":null,"statut_reponse":"ok","observation":null,"niveau_fiabilite":3,"ordre":1,"created_at":"2026-04-24 10:08:19","updated_at":"2026-04-24 10:08:19","tiers":"tiers"}]}', 7, '2026-04-24 09:31:51'),
	(2, 'XIV', 'outil_observation', 3, 3, 'O1', '{"date_observation":"2026-04-25","heure_debut":"13:18","heure_fin":"16:18","localisation":null,"objectif_audit":"Vérification : Vérifier la conformité des procédures de réception et contrôle qualité des matières premières agricoles","points_forts":"force 1","points_faibles":"faiblesse1","conclusion":null,"constats":[{"id":1,"observation_id":3,"element_observe":"manque de contrôle","conforme_referentiel":"oui","conforme":null,"ecart_constate":null,"risque_associe":"rique de perte","preuve":null,"ordre":1,"created_at":"2026-04-24 10:21:23","updated_at":"2026-04-24 10:21:23"},{"element_observe":"manque de contrôle 2","conforme_referentiel":null,"ecart_constate":null,"risque_associe":null,"preuve":null}]}', 7, '2026-04-24 10:05:40'),
	(3, 'I', 'outil_entretiens', 8, 4, 'ADI-002-26', '{"date":null,"interlocuteurs":null,"objectif_audit":"Vérification : Vérifier l\'efficacité des contrôles qualité sur les matières premières agricoles à réception","synthese":"Excellente expérience en audit IFS Food et BRC dans l’industrie des jus de fruits. Maîtrise parfaite de la traçabilité lot par lot et des risques microbiologiques (Salmonella sur fruits tropicaux). Très bon sens de la diplomatie lors des audits terrain.","sig_auditeur":"IMOROU nawal","sig_interlocuteur":null,"questions":[{"type":"Ouverte","question":"- Parlez-nous de votre parcours.\\n- Avez-vous déjà réalisé des audits internes dans le secteur alimentaire ou agroalimentaire ?\\n- Quelle est votre expérience avec les référentiels (IFS, BRC, HACCP, ISO 22000, GlobalGAP…) ?","reponse":"lus de 85\\/100 → Très bon candidat (priorité)\\nEntre 70 et 85 → Bon candidat (à discuter en équipe)"}],"_code":"I","_key":"I::O2::T_O2::2"}', 7, '2026-04-28 14:01:08'),
