-- Listage de la structure de table fruitiva. outil_hierarchisation_risques_documents
CREATE TABLE IF NOT EXISTS `outil_hierarchisation_risques_documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `fiche_id` bigint(20) unsigned NOT NULL,
  `mission_id` bigint(20) unsigned NOT NULL,
  `assignment_id` bigint(20) unsigned DEFAULT NULL,
  `file_name` varchar(500) NOT NULL,
  `original_name` varchar(500) NOT NULL,
  `file_path` varchar(1000) NOT NULL,
  `file_size` bigint(20) unsigned DEFAULT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `file_extension` varchar(20) DEFAULT NULL,
  `word_content_html` longtext DEFAULT NULL COMMENT 'HTML converti du Word pour aperçu/édition',
  `status` enum('draft','validated','rejected') NOT NULL DEFAULT 'draft',
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `validation_comment` text DEFAULT NULL,
  `uploaded_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fiche_id` (`fiche_id`),
  CONSTRAINT `fk_hier_doc_fiche` FOREIGN KEY (`fiche_id`) REFERENCES `outil_hierarchisation_risques` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

