-- Listage de la structure de table fruitiva. outil_hierarchisation_risques_lignes
CREATE TABLE IF NOT EXISTS `outil_hierarchisation_risques_lignes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `fiche_id` bigint(20) unsigned NOT NULL,
  `libelle` varchar(500) NOT NULL COMMENT 'Risque identifié',
  `categorie` varchar(100) DEFAULT NULL COMMENT 'Type de risque',
  `causes` text DEFAULT NULL,
  `consequences` text DEFAULT NULL,
  `probabilite` tinyint(3) unsigned NOT NULL DEFAULT 1 COMMENT '1=Faible 2=Modéré 3=Fort',
  `impact` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `criticite` tinyint(3) unsigned GENERATED ALWAYS AS (`probabilite` * `impact`) STORED,
  `niveau_risque` varchar(20) GENERATED ALWAYS AS (case when `probabilite` * `impact` >= 7 then 'Fort' when `probabilite` * `impact` >= 4 then 'Modéré' else 'Faible' end) STORED,
  `traitement` text DEFAULT NULL,
  `responsable` varchar(255) DEFAULT NULL,
  `echeance` date DEFAULT NULL,
  `from_mission` tinyint(1) NOT NULL DEFAULT 0,
  `risk_id` bigint(20) unsigned DEFAULT NULL,
  `ordre` smallint(5) unsigned NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_hrl_fiche` (`fiche_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

