-- Listage de la structure de table fruitiva. outil_observation
CREATE TABLE IF NOT EXISTS `outil_observation` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL DEFAULT '',
  `mission_id` bigint(20) unsigned NOT NULL,
  `assignment_id` bigint(20) unsigned DEFAULT NULL,
  `procedure_code` varchar(80) DEFAULT NULL,
  `test_ref` varchar(80) DEFAULT NULL,
  `obj_num` varchar(20) DEFAULT NULL,
  `date_observation` date DEFAULT NULL,
  `heure_debut` varchar(10) DEFAULT NULL,
  `heure_fin` varchar(10) DEFAULT NULL,
  `auditeur` varchar(255) DEFAULT NULL,
  `localisation` varchar(255) DEFAULT NULL,
  `interlocuteurs_presents` text DEFAULT NULL,
  `objectif_audit` text DEFAULT NULL,
  `tache_local_observer` text DEFAULT NULL COMMENT 'Tâche/Local à observer',
  `elements_verifier` text DEFAULT NULL,
  `pieces_attendues` text DEFAULT NULL,
  `intitule_probleme` text DEFAULT NULL,
  `faits_constates` text DEFAULT NULL,
  `critere_referentiel` text DEFAULT NULL,
  `causes_json` text DEFAULT NULL,
  `causes_autres` text DEFAULT NULL,
  `consequences_json` text DEFAULT NULL,
  `consequences_description` text DEFAULT NULL,
  `niveau_maitrise` varchar(30) DEFAULT NULL,
  `niveau_controle` varchar(30) DEFAULT NULL,
  `niveau_synthese` varchar(30) DEFAULT NULL,
  `foci_id` bigint(20) unsigned DEFAULT NULL COMMENT 'FK fiche_observation_ci.id',
  `points_forts` text DEFAULT NULL,
  `points_faibles` text DEFAULT NULL COMMENT 'Points faibles / Dysfonctionnements',
  `conclusion` text DEFAULT NULL,
  `ia_result` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`ia_result`)),
  `ia_score` decimal(4,1) DEFAULT NULL,
  `ia_generated_at` timestamp NULL DEFAULT NULL,
  `auto_save_at` timestamp NULL DEFAULT NULL,
  `statut` enum('draft','in_review','validated','rejected') NOT NULL DEFAULT 'draft',
  `validation_note` text DEFAULT NULL,
  `commentaire_validation` text DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_obs_mission` (`mission_id`),
  KEY `idx_obs_proc` (`procedure_code`,`test_ref`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Outil XIV';

