-- Listage de la structure de table fruitiva. process_contracts
CREATE TABLE IF NOT EXISTS `process_contracts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `process_id` bigint(20) unsigned NOT NULL,
  `entity_id` bigint(20) unsigned NOT NULL,
  `function_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL COMMENT 'ID utilisateur externe (non FK)',
  `owner` varchar(255) DEFAULT NULL COMMENT 'Propriétaire du processus',
  `purpose` text DEFAULT NULL COMMENT 'Finalité du processus',
  `status` enum('draft','active','archived') NOT NULL DEFAULT 'draft',
  `inputs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Données d''entrée du processus' CHECK (json_valid(`inputs`)),
  `outputs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Données de sortie avec détails' CHECK (json_valid(`outputs`)),
  `resources` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Ressources du processus' CHECK (json_valid(`resources`)),
  `activity_indicators` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Indicateurs d''activité' CHECK (json_valid(`activity_indicators`)),
  `performance_indicators` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Indicateurs de performance' CHECK (json_valid(`performance_indicators`)),
  `attachments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Chemins des fichiers (inputs/outputs/resources)' CHECK (json_valid(`attachments`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `archived_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_pc_process_context` (`process_id`,`entity_id`,`function_id`),
  KEY `idx_pc_process` (`process_id`),
  KEY `idx_pc_entity` (`entity_id`),
  KEY `idx_pc_function` (`function_id`),
  KEY `idx_pc_user` (`user_id`),
  KEY `idx_pc_status` (`status`),
  CONSTRAINT `process_contracts_entity_id_foreign` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`) ON DELETE CASCADE,
  CONSTRAINT `process_contracts_function_id_foreign` FOREIGN KEY (`function_id`) REFERENCES `functions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `process_contracts_process_id_foreign` FOREIGN KEY (`process_id`) REFERENCES `processes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

