  CONSTRAINT `process_contract_histories_contract_id_foreign` FOREIGN KEY (`contract_id`) REFERENCES `process_contracts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

