  `categorie_code` varchar(10) NOT NULL,
  `ref_controle` varchar(20) NOT NULL,
  `ref_reglementaire` varchar(150) DEFAULT NULL,
  `intitule_procedure` text NOT NULL,
  `point_controle` text NOT NULL,
  `preuves_attendues` text DEFAULT NULL,
  `ordre` smallint(5) unsigned NOT NULL DEFAULT 0,
  `actif` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
