-- Listage des données de la table fruitiva.ref_transactions_criteres : ~48 rows (environ)
INSERT INTO `ref_transactions_criteres` (`id`, `categorie_code`, `ref_controle`, `ref_reglementaire`, `intitule_procedure`, `point_controle`, `preuves_attendues`, `ordre`, `actif`) VALUES
	(1, 'REC', 'REC-01', 'Art. 15 LOLF 2013-14 / Art. 12 Décret 2014-571', 'Autorisation de perception des recettes', 'Toute recette est perçue sur la base d\'une autorisation légale ou réglementaire en vigueur.', 'Textes d\'assiette, décision d\'autorisation, bordereau d\'émission de titre de recette', 10, 1),
	(2, 'REC', 'REC-02', 'Art. 16 LOLF 2013-14', 'Émission des titres de recettes', 'Les titres de recettes sont émis par l\'ordonnateur ou son délégué avant tout encaissement.', 'Titres de recettes signés, registre des titres, délégation de signature', 20, 1),
	(3, 'REC', 'REC-03', 'Art. 18 Décret 2014-571', 'Prise en charge des titres par le comptable', 'Le comptable prend en charge les titres de recettes avant encaissement et les enregistre dans la comptabilité.', 'Registre de prise en charge, accusé de réception, journal de caisse', 30, 1),
	(4, 'REC', 'REC-04', 'Art. 20 Décret 2014-571', 'Recouvrement des créances', 'Les créances de l\'État font l\'objet de relances et de poursuites en cas de non-paiement dans les délais.', 'Relevés de créances, lettres de relance, états de recouvrement, taux de recouvrement', 40, 1),
	(5, 'REC', 'REC-05', 'Art. 22 Décret 2014-571', 'Versement des recettes encaissées', 'Les recettes encaissées sont versées intégralement et sans délai dans le compte du Trésor.', 'Bordereaux de versement, relevés bancaires, états de rapprochement caisse/Trésor', 50, 1),
	(6, 'REC', 'REC-06', 'Art. 25 Décret 2014-571', 'Contrôle de l\'exhaustivité des recettes', 'L\'exhaustivité des recettes est vérifiée par rapprochement entre les titres émis et les encaissements réels.', 'États de rapprochement, listing des titres non soldés, attestation de contrôle', 60, 1),
	(7, 'DEP', 'DEP-01', 'Art. 30 LOLF 2013-14 / Art. 35 Décret 2014-571', 'Engagement des dépenses', 'Toute dépense est engagée dans la limite des crédits ouverts et fait l\'objet d\'un acte d\'engagement visé.', 'Acte d\'engagement visé, disponibilité des crédits, fiche de visa', 70, 1),
	(8, 'DEP', 'DEP-02', 'Art. 32 LOLF 2013-14', 'Liquidation des dépenses', 'La liquidation vérifie la réalité de la dette et arrête le montant exact de la dépense.', 'Factures, bons de livraison, PV de réception, certificat de service fait', 80, 1),
	(9, 'DEP', 'DEP-03', 'Art. 33 LOLF 2013-14', 'Ordonnancement des dépenses', 'L\'ordonnancement est effectué par l\'ordonnateur habilité sur la base des pièces justificatives complètes.', 'Ordonnance de paiement signée, dossier de liquidation complet, habilitation de l\'ordonnateur', 90, 1),
	(10, 'DEP', 'DEP-04', 'Art. 40 Décret 2014-571', 'Contrôle préalable du comptable', 'Le comptable effectue les contrôles de régularité avant paiement (qualité ordonnateur, disponibilité crédits, pièces justificatives).', 'Visa du comptable, motifs de rejet éventuels, registre des contrôles préalables', 100, 1),
	(11, 'DEP', 'DEP-05', 'Art. 42 Décret 2014-571', 'Délais de paiement', 'Les délais réglementaires de paiement sont respectés (30 jours en régime normal).', 'Dates d\'ordonnancement et de paiement, calcul des délais, intérêts moratoires éventuels', 110, 1),
	(12, 'DEP', 'DEP-06', 'Art. 45 Décret 2014-571', 'Pièces justificatives des dépenses', 'Les dossiers de dépenses comportent toutes les pièces justificatives réglementaires.', 'Checklist des pièces, dossiers complets archivés, attestation de complétude', 120, 1),
	(13, 'TRE', 'TRE-01', 'Art. 50 Décret 2014-571', 'Unicité du compte de Trésor', 'Tous les fonds publics sont déposés dans les comptes du Trésor conformément au principe d\'unicité.', 'Relevés des comptes ouverts, attestation d\'unicité, liste des comptes autorisés', 130, 1),
	(14, 'TRE', 'TRE-02', 'Art. 52 Décret 2014-571', 'Gestion de la caisse', 'La caisse est tenue régulièrement, vérifiée périodiquement et les excédents sont versés au Trésor.', 'Procès-verbaux de caisse, registre de caisse, bordereaux de versement', 140, 1),
	(15, 'TRE', 'TRE-03', 'Art. 54 Décret 2014-571', 'Rapprochement bancaire', 'Les rapprochements entre les soldes comptables et les relevés bancaires sont effectués mensuellement.', 'États de rapprochement bancaire signés, écarts documentés et justifiés', 150, 1),
	(16, 'TRE', 'TRE-04', 'Art. 56 Décret 2014-571', 'Plan de trésorerie', 'Un plan prévisionnel de trésorerie est établi et actualisé régulièrement.', 'Plan de trésorerie approuvé, actualisations périodiques, écarts analysés', 160, 1),
	(17, 'TRE', 'TRE-05', 'Art. 58 Décret 2014-571', 'Gestion des valeurs inactives', 'Les valeurs inactives (timbres, chéquiers, carnets) sont gérées et contrôlées rigoureusement.', 'Registre des valeurs inactives, inventaires, signatures de contrôle', 170, 1),
	(18, 'TRE', 'TRE-06', 'Art. 60 Décret 2014-571', 'Sécurisation des fonds', 'Les fonds sont conservés dans des conditions de sécurité adéquates (coffre-fort, accès restreint).', 'Attestation de sécurité, procédures de sécurisation, inventaire physique des fonds', 180, 1),
	(19, 'REG', 'REG-01', 'Art. 65 Décret 2014-571', 'Institution des régies', 'Les régies sont instituées par décision de l\'autorité compétente avec désignation du régisseur.', 'Décision d\'institution, acte de nomination du régisseur, cautionnement', 190, 1),
	(20, 'REG', 'REG-02', 'Art. 67 Décret 2014-571', 'Justification des dépenses de régie', 'Le régisseur justifie ses dépenses dans les délais réglementaires auprès du comptable principal.', 'Pièces justificatives transmises, délais respectés, quittances du comptable', 200, 1),
	(21, 'REG', 'REG-03', 'Art. 69 Décret 2014-571', 'Plafond des régies', 'Le montant des avances en régie ne dépasse pas le plafond autorisé.', 'Décision fixant le plafond, relevé des avances, attestation de conformité', 210, 1),
	(22, 'REG', 'REG-04', 'Art. 71 Décret 2014-571', 'Vérification des régies', 'Les régies font l\'objet de vérifications inopinées par le comptable principal ou son représentant.', 'PV de vérification inopinée, date et résultats, actions correctives', 220, 1),
	(23, 'REG', 'REG-05', 'Art. 73 Décret 2014-571', 'Reconstitution des avances', 'Les avances de régie sont reconstituées après justification selon les procédures établies.', 'Demandes de reconstitution, pièces justificatives, délais de reconstitution', 230, 1),
	(24, 'REG', 'REG-06', 'Art. 75 Décret 2014-571', 'Clôture des régies', 'Les régies sont clôturées et apurées en fin de gestion ou lors du changement de régisseur.', 'PV de clôture, reversement des soldes, quittance du comptable', 240, 1),
	(25, 'PAI', 'PAI-01', 'Art. 80 Décret 2014-571', 'Identification des bénéficiaires', 'L\'identité et la qualité des bénéficiaires sont vérifiées avant tout paiement.', 'Pièces d\'identité, attestations de qualité, registre des bénéficiaires', 250, 1),
	(26, 'PAI', 'PAI-02', 'Art. 82 Décret 2014-571', 'Modes de paiement autorisés', 'Les paiements sont effectués par les modes autorisés (virement bancaire, chèque) ; les paiements en espèces sont limités aux cas prévus.', 'Ordres de virement, relevés bancaires, justification des paiements en espèces', 260, 1),
	(27, 'PAI', 'PAI-03', 'Art. 84 Décret 2014-571', 'Signature des paiements', 'Les ordres de paiement sont signés par les personnes habilitées selon la délégation en vigueur.', 'Ordres de paiement signés, liste des signataires habilités, délégations de signature', 270, 1),
	(28, 'PAI', 'PAI-04', 'Art. 86 Décret 2014-571', 'Prévention des doubles paiements', 'Des contrôles sont en place pour éviter les doubles paiements (numérotation, annulation des pièces).', 'Registre des paiements, pièces tamponnées PAYÉ, contrôle de doublons', 280, 1),
	(29, 'PAI', 'PAI-05', 'Art. 88 Décret 2014-571', 'Paiement des salaires et indemnités', 'Les états de paie sont vérifiés et les paiements correspondent aux états certifiés.', 'États de paie certifiés, relevés de virements, rapprochement paie/comptabilité', 290, 1),
	(30, 'PAI', 'PAI-06', 'Art. 90 Décret 2014-571', 'Traçabilité des paiements', 'Chaque paiement est traçable de l\'ordonnancement jusqu\'au relevé bancaire.', 'Chaîne de paiement documentée, référence bancaire, lettrage comptable', 300, 1),
	(31, 'COM', 'COM-01', 'Art. 95 Décret 2014-571', 'Tenue de la comptabilité des deniers', 'La comptabilité des recettes et des dépenses est tenue régulièrement et sincèrement.', 'Journal de caisse, grand livre, balance mensuelle signée', 310, 1),
	(32, 'COM', 'COM-02', 'Art. 97 Décret 2014-571', 'Comptabilité des matières', 'Les biens et valeurs non monétaires sont enregistrés dans une comptabilité des matières.', 'Registre des matières, inventaire physique, fiches de stock', 320, 1),
	(33, 'COM', 'COM-03', 'Art. 99 Décret 2014-571', 'Imputations budgétaires', 'Toute opération est imputée au bon chapitre, article et ligne budgétaire.', 'Nomenclature budgétaire, instructions d\'imputation, contrôle d\'imputation', 330, 1),
	(34, 'COM', 'COM-04', 'Art. 101 Décret 2014-571', 'Périodicité des arrêtés de comptes', 'Les comptes sont arrêtés mensuellement et les soldes rapprochés avec les données budgétaires.', 'Arrêtés mensuels signés, états de rapprochement budget/comptabilité', 340, 1),
	(35, 'COM', 'COM-05', 'Art. 103 Décret 2014-571', 'Enregistrement des opérations hors budget', 'Les opérations hors budget (avances, prêts, cautionnements) sont comptabilisées séparément.', 'Comptes spéciaux, registre des avances, états de situation', 350, 1),
	(36, 'COM', 'COM-06', 'Art. 105 Décret 2014-571', 'Production du compte de gestion', 'Le compte de gestion est produit dans les délais réglementaires.', 'Compte de gestion signé, date de production, accusé de réception Cour des Comptes', 360, 1),
	(37, 'CTR', 'CTR-01', 'Art. 110 Décret 2014-571', 'Séparation des fonctions ordonnateur/comptable', 'Les fonctions d\'ordonnateur et de comptable sont strictement séparées et exercées par des personnes différentes.', 'Organigramme, fiches de poste, absence de cumul de fonctions', 370, 1),
	(38, 'CTR', 'CTR-02', 'Art. 112 Décret 2014-571', 'Responsabilité personnelle et pécuniaire du comptable', 'Le comptable connaît et assume sa responsabilité personnelle et pécuniaire sur les opérations réalisées.', 'Acte de nomination, cautionnement, déclaration de prise en charge', 380, 1),
	(39, 'CTR', 'CTR-03', 'Art. 114 Décret 2014-571', 'Contrôles périodiques par la hiérarchie', 'La hiérarchie effectue des contrôles périodiques sur les opérations de trésorerie.', 'PV de contrôle hiérarchique, fréquence, résultats et suivi', 390, 1),
	(40, 'CTR', 'CTR-04', 'Art. 116 Décret 2014-571', 'Gestion des anomalies et écarts', 'Les anomalies et écarts détectés font l\'objet d\'un traitement documenté et d\'un suivi.', 'Registre des anomalies, actions correctives, délais de traitement', 400, 1),
	(41, 'CTR', 'CTR-05', 'Art. 118 Décret 2014-571', 'Déclaration des disponibilités', 'Les disponibilités sont déclarées régulièrement à l\'autorité de tutelle.', 'États de disponibilités signés, fréquence de déclaration, accusés de réception', 410, 1),
	(42, 'CTR', 'CTR-06', 'Art. 120 Décret 2014-571', 'Contrôle de l\'Inspection Générale des Finances', 'Les contrôles de l\'IGF sont facilités et les observations sont traitées dans les délais.', 'Rapports IGF, réponses aux observations, plan d\'action corrective', 420, 1),
	(43, 'ARC', 'ARC-01', 'Art. 125 Décret 2014-571', 'Conservation des pièces justificatives', 'Toutes les pièces justificatives des opérations sont conservées pendant la durée réglementaire (10 ans).', 'Inventaire des archives, conditions de conservation, plan d\'archivage', 430, 1),
	(44, 'ARC', 'ARC-02', 'Art. 127 Décret 2014-571', 'Classement et indexation des documents', 'Les documents comptables sont classés de manière à permettre leur accès et leur contrôle rapides.', 'Plan de classement, index des documents, délais de recherche', 440, 1),
	(45, 'ARC', 'ARC-03', 'Art. 129 Décret 2014-571', 'Archivage électronique', 'Si des systèmes d\'archivage électronique sont utilisés, ils garantissent l\'intégrité et la pérennité des données.', 'Système d\'archivage certifié, sauvegardes, procédure de restauration', 450, 1),
	(46, 'ARC', 'ARC-04', 'Art. 131 Décret 2014-571', 'Transmission des comptes à la Cour des Comptes', 'Les comptes annuels sont transmis à la Cour des Comptes dans les délais légaux.', 'Accusé de réception Cour des Comptes, date de transmission, complétude du dossier', 460, 1),
	(47, 'ARC', 'ARC-05', 'Art. 133 Décret 2014-571', 'Communication des pièces aux contrôleurs', 'Les pièces justificatives sont communiquées sans délai aux contrôleurs (IGF, Cour des Comptes, auditeurs).', 'Registre des communications, délais de réponse, attestations de remise', 470, 1),
	(48, 'ARC', 'ARC-06', 'Art. 135 Décret 2014-571', 'Destruction contrôlée des archives', 'La destruction des archives est effectuée selon la procédure réglementaire après l\'expiration des délais de conservation.', 'PV de destruction, autorisation préalable, liste des documents détruits', 480, 1);

-- Listage de la structure de table fruitiva. reunion_clotures
CREATE TABLE IF NOT EXISTS `reunion_clotures` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(60) DEFAULT NULL,
  `mission_id` bigint(20) unsigned NOT NULL,
  `assignment_id` bigint(20) unsigned DEFAULT NULL,
  `code_mission` varchar(50) DEFAULT NULL,
  `entite` varchar(255) DEFAULT NULL,
  `intitule_mission` varchar(500) DEFAULT NULL,
  `date_reunion` date DEFAULT NULL,
  `heure_debut` time DEFAULT NULL,
  `heure_fin` time DEFAULT NULL,
  `lieu` varchar(255) DEFAULT NULL,
  `preside_par` varchar(255) DEFAULT NULL,
  `secretaire_seance` varchar(255) DEFAULT NULL,
  `norme_mpa` varchar(100) DEFAULT 'MPA 2400 – 2410-1',
  `statut` enum('draft','in_review','validated') DEFAULT 'draft',
  `validation_note` text DEFAULT NULL,
  `validated_by` bigint(20) unsigned DEFAULT NULL,
  `validated_at` timestamp NULL DEFAULT NULL,
  `conclusion_generale` text DEFAULT NULL,
  `observations_finales` text DEFAULT NULL,
  `date_rapport` date DEFAULT NULL,
  `delais_plan_action` varchar(255) DEFAULT NULL,
  `modalites_suivi` text DEFAULT NULL,
  `participants` longtext DEFAULT NULL COMMENT 'JSON array participants',
  `tenant_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_rc_mission` (`mission_id`),
  KEY `idx_rc_statut` (`statut`),
  KEY `idx_rc_code` (`code`),
  KEY `idx_rc_assignment` (`assignment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

