-- Listage de la structure de table fruitiva. risks
CREATE TABLE IF NOT EXISTS `risks` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint(20) unsigned NOT NULL,
  `project_id` bigint(20) unsigned DEFAULT NULL,
  `audit_session_id` bigint(20) unsigned DEFAULT NULL,
  `entity_id` bigint(20) unsigned DEFAULT NULL,
  `process_id` bigint(20) unsigned DEFAULT NULL,
  `activity_id` bigint(20) unsigned DEFAULT NULL,
  `risk_type_id` bigint(20) unsigned DEFAULT NULL,
  `code` varchar(50) NOT NULL,
  `label` varchar(255) NOT NULL,
  `description` longtext DEFAULT NULL,
  `activity_code` varchar(50) DEFAULT NULL,
  `frequency_level_id` bigint(20) unsigned DEFAULT NULL,
  `frequency_net` decimal(3,1) DEFAULT NULL,
  `impact_level_id` bigint(20) unsigned DEFAULT NULL,
  `impact_net` decimal(3,1) DEFAULT NULL,
  `criticality` int(11) DEFAULT NULL,
  `owner` varchar(255) DEFAULT NULL,
  `control_procedure` longtext DEFAULT NULL,
  `status` enum('identified','assessed','mitigated','monitored','closed') DEFAULT 'identified',
  `year` int(11) DEFAULT 2026,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `owner_function_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_project` (`project_id`),
  KEY `idx_audit_session` (`audit_session_id`),
  KEY `idx_entity` (`entity_id`),
  KEY `idx_process` (`process_id`),
  KEY `idx_activity` (`activity_id`),
  KEY `idx_risk_type` (`risk_type_id`),
  KEY `idx_frequency_level` (`frequency_level_id`),
  KEY `idx_impact_level` (`impact_level_id`),
  KEY `idx_status` (`status`),
  KEY `idx_year` (`year`),
  CONSTRAINT `fk_risk_frequency` FOREIGN KEY (`frequency_level_id`) REFERENCES `risk_frequency_levels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_risk_impact` FOREIGN KEY (`impact_level_id`) REFERENCES `risk_impact_levels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_risk_session` FOREIGN KEY (`audit_session_id`) REFERENCES `audit_sessions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_risk_type` FOREIGN KEY (`risk_type_id`) REFERENCES `risk_types` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

