-- Listage de la structure de table fruitiva. risk_activity_indicators
CREATE TABLE IF NOT EXISTS `risk_activity_indicators` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint(20) unsigned NOT NULL,
  `risk_id` bigint(20) unsigned DEFAULT NULL,
  `process_id` bigint(20) unsigned DEFAULT NULL,
  `function_id` bigint(20) unsigned DEFAULT NULL,
  `code` varchar(50) NOT NULL,
  `label` varchar(255) NOT NULL,
  `description` longtext DEFAULT NULL,
  `metric_name` varchar(255) NOT NULL,
  `unit` varchar(50) DEFAULT NULL,
  `frequency` enum('daily','weekly','monthly','quarterly','yearly') DEFAULT 'monthly',
  `target_value` decimal(8,2) DEFAULT NULL,
  `min_threshold` decimal(8,2) DEFAULT NULL,
  `max_threshold` decimal(8,2) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_risk` (`risk_id`),
  CONSTRAINT `fk_indicator_risk` FOREIGN KEY (`risk_id`) REFERENCES `risks` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

