-- Listage de la structure de table fruitiva. risk_assessments
CREATE TABLE IF NOT EXISTS `risk_assessments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint(20) unsigned NOT NULL,
  `risk_id` bigint(20) unsigned NOT NULL,
  `project_id` bigint(20) unsigned DEFAULT NULL,
  `code` varchar(50) NOT NULL,
  `assessment_date` date NOT NULL,
  `type` enum('initial','periodic','ad_hoc','post_incident') DEFAULT 'periodic',
  `findings` longtext DEFAULT NULL,
  `rating` enum('green','yellow','red') DEFAULT 'green',
  `risk_score` decimal(5,2) DEFAULT NULL,
  `evidence` longtext DEFAULT NULL,
  `recommendations` longtext DEFAULT NULL,
  `assessed_by` bigint(20) unsigned DEFAULT NULL,
  `next_assessment_date` date DEFAULT NULL,
  `status` enum('draft','completed','approved','action_required') DEFAULT 'draft',
