-- Listage de la structure de procédure fruitiva. sp_log_audit_score_change
DELIMITER //
CREATE PROCEDURE `sp_log_audit_score_change`(
  IN p_process_id BIGINT,
  IN p_entity_id BIGINT,
  IN p_factor_id BIGINT,
  IN p_old_score INT,
  IN p_new_score INT,
  IN p_old_average DECIMAL(5,2),
  IN p_new_average DECIMAL(5,2),
  IN p_old_ranking INT,
  IN p_new_ranking INT,
  IN p_change_reason VARCHAR(255),
  IN p_changed_by BIGINT
)
BEGIN
  INSERT INTO `audit_process_scoring_history` (
    process_id, entity_id, factor_id, old_score, new_score,
    old_average, new_average, old_ranking, new_ranking,
    change_reason, changed_by, change_date
  )
  VALUES (
    p_process_id, p_entity_id, p_factor_id, p_old_score, p_new_score,
    p_old_average, p_new_average, p_old_ranking, p_new_ranking,
    p_change_reason, p_changed_by, CURDATE()
  );
END//
DELIMITER ;

-- Listage de la structure de procédure fruitiva. sp_recalculate_all_audit_rankings
DELIMITER //
CREATE PROCEDURE `sp_recalculate_all_audit_rankings`(
  IN p_entity_id BIGINT
)
BEGIN
  DECLARE v_done INT DEFAULT 0;
  DECLARE v_process_id BIGINT;
  DECLARE cur_processes CURSOR FOR
    SELECT DISTINCT process_id 
    FROM `audit_process_scores`
    WHERE entity_id = p_entity_id
    UNION
    SELECT process_id FROM `audit_process_rankings` WHERE entity_id = p_entity_id;
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

  OPEN cur_processes;
  
  process_loop: LOOP
    FETCH cur_processes INTO v_process_id;
    IF v_done THEN
      LEAVE process_loop;
    END IF;
    
    CALL `sp_recalculate_audit_ranking`(v_process_id, p_entity_id);
  END LOOP;
  
  CLOSE cur_processes;
END//
DELIMITER ;

-- Listage de la structure de procédure fruitiva. sp_recalculate_audit_ranking
DELIMITER //
CREATE PROCEDURE `sp_recalculate_audit_ranking`(
  IN p_process_id BIGINT,
  IN p_entity_id BIGINT
)
BEGIN
  DECLARE v_total_score DECIMAL(8,2);
  DECLARE v_factor_count INT;
  DECLARE v_average_score DECIMAL(5,2);
  DECLARE v_rating_label VARCHAR(50);
  DECLARE v_ranking_position INT;
  DECLARE v_total_processes INT;
  DECLARE v_percentage DECIMAL(5,2);
  DECLARE v_priority_status VARCHAR(20);

  -- 1️⃣ CALCULER LA SOMME DES SCORES
  SELECT COALESCE(SUM(aps.score), 0)
  INTO v_total_score
  FROM `audit_process_scores` aps
  WHERE aps.process_id = p_process_id 
  AND aps.entity_id = p_entity_id;

  -- 2️⃣ COMPTER LES FACTEURS ACTIFS
  SELECT COUNT(*)
  INTO v_factor_count
  FROM `audit_factors`
  WHERE is_active = 1;

  -- 3️⃣ CALCULER LA MOYENNE
  SET v_average_score = IF(v_factor_count > 0, ROUND(v_total_score / v_factor_count, 2), 0);

  -- 4️⃣ DÉTERMINER LE RATING LABEL BASÉ SUR LA MOYENNE
  SET v_rating_label = CASE
    WHEN v_average_score >= 4.5 THEN 'Excellent'
    WHEN v_average_score >= 4.0 THEN 'Très Bon'
    WHEN v_average_score >= 3.0 THEN 'Bon'
    WHEN v_average_score >= 2.0 THEN 'Moyen'
    WHEN v_average_score > 0 THEN 'Faible'
    ELSE NULL
  END;

  -- 5️⃣ DÉTERMINER LA PRIORITÉ
  SET v_priority_status = CASE
    WHEN v_average_score >= 4.0 THEN 'Basse'
    WHEN v_average_score >= 3.5 THEN 'Moyenne'
    WHEN v_average_score >= 2.5 THEN 'Haute'
    WHEN v_average_score > 0 THEN 'Critique'
    ELSE 'N/A'
  END;

  -- 6️⃣ CALCULER LE RANG AU SEIN DE L'ENTITÉ
  SELECT COUNT(*) + 1
  INTO v_ranking_position
  FROM `audit_process_rankings`
  WHERE entity_id = p_entity_id
  AND average_score > v_average_score
  AND process_id != p_process_id;

  -- 7️⃣ CALCULER LE POURCENTAGE
  SELECT COUNT(*)
  INTO v_total_processes
  FROM `audit_process_rankings`
  WHERE entity_id = p_entity_id;

  SET v_percentage = IF(v_total_processes > 0, 
    ROUND((v_ranking_position / v_total_processes) * 100, 2), 
    0);

  -- 8️⃣ INSÉRER OU METTRE À JOUR LE RANKING
  INSERT INTO `audit_process_rankings` (
    process_id, entity_id, total_score, average_score, rating_label,
    ranking_position, ranking_percentage, priority_status,
    last_evaluation_date, number_of_evaluations, updated_at
  )
  VALUES (
    p_process_id, p_entity_id, v_total_score, v_average_score, v_rating_label,
    v_ranking_position, v_percentage, v_priority_status,
    CURDATE(), 1, NOW()
  )
  ON DUPLICATE KEY UPDATE
    total_score = v_total_score,
    average_score = v_average_score,
    rating_label = v_rating_label,
    ranking_position = v_ranking_position,
    ranking_percentage = v_percentage,
    priority_status = v_priority_status,
    last_evaluation_date = CURDATE(),
    number_of_evaluations = number_of_evaluations + 1,
    updated_at = NOW();

END//
DELIMITER ;

-- Listage de la structure de procédure fruitiva. sp_recalcul_score_global
DELIMITER //
CREATE PROCEDURE `sp_recalcul_score_global`(IN p_form_id BIGINT UNSIGNED)
BEGIN
    DECLARE v_score DECIMAL(5,2);

    SELECT ROUND(AVG(score), 2)
    INTO   v_score
    FROM   analyse_conformite_items
    WHERE  analyse_conformite_id = p_form_id
    AND    reponse IS NOT NULL;

    UPDATE analyse_conformites
    SET    score_global = v_score,
           updated_at   = NOW()
    WHERE  id = p_form_id;
END//
DELIMITER ;

