-- Listage de la structure de table fruitiva. user_functions
CREATE TABLE IF NOT EXISTS `user_functions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `function_id` bigint(20) unsigned NOT NULL,
  `entity_id` bigint(20) unsigned DEFAULT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT 0,
  `role_label` varchar(100) DEFAULT NULL,
  `assigned_at` timestamp NULL DEFAULT NULL,
  `revoked_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uf_unique_per_entity` (`user_id`,`function_id`,`entity_id`),
  KEY `uf_user_primary_idx` (`user_id`,`is_primary`),
  KEY `uf_function_entity_idx` (`function_id`,`entity_id`),
  KEY `uf_entity_idx` (`entity_id`),
  CONSTRAINT `uf_entity_fk` FOREIGN KEY (`entity_id`) REFERENCES `entities` (`id`) ON DELETE SET NULL,
  CONSTRAINT `uf_function_fk` FOREIGN KEY (`function_id`) REFERENCES `functions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `uf_user_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

