-- Listage des données de la table fruitiva._archive_referentiel_marches_criteres : ~44 rows (environ)
INSERT INTO `_archive_referentiel_marches_criteres` (`id`, `phase`, `ref`, `art`, `proc`, `point`, `preuves`, `ordre`, `created_at`, `updated_at`) VALUES
	(1, 'PLA', 'PLA-01', 'Art. 6, 7 – Décret 2009-277', 'Plan de Passation des Marchés (PPM)', 'Un PPM annuel est élaboré, approuvé et publié dans les délais réglementaires.', 'PPM signé, date d\'approbation, avis de publication ARMP', 10, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(2, 'PLA', 'PLA-02', 'Art. 8 – Décret 2009-277', 'Estimation préalable et budget', 'Chaque marché prévu est accompagné d\'une estimation préalable budgétée et validée.', 'Fiches d\'estimation, visas de la Direction Financière, ligne budgétaire allouée', 20, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(3, 'PLA', 'PLA-03', 'Art. 9 – Décret 2009-277', 'Choix de la procédure de passation', 'La procédure retenue (AOO, AON, DC, gré à gré) est justifiée par les seuils et la nature du marché.', 'Note de justification, tableau des seuils, avis de non-objection si requis', 30, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(4, 'PLA', 'PLA-04', 'Art. 10, 11 – Décret 2009-277', 'Découpage et regroupement des marchés', 'L\'entité n\'a pas procédé au fractionnement artificiel des marchés pour contourner les seuils.', 'État récapitulatif des marchés, note explicative des lots, attestation du responsable', 40, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(5, 'PLA', 'PLA-05', 'Art. 12 – Décret 2009-277', 'Publication du PPM et mise à jour', 'Le PPM est mis à jour au moins trimestriellement et les modifications sont publiées.', 'PPM révisé, avis de modification ARMP/journal, dates de mise à jour', 50, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(6, 'DAO', 'DAO-01', 'Art. 35, 36 – Décret 2009-277', 'Élaboration du dossier d\'appel d\'offres', 'Le DAO est conforme aux dossiers types ARMP et comprend tous les documents obligatoires.', 'DAO complet (ICAO, CPS, DPQ, CCAG, formulaires), visa ARMP si requis', 60, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(7, 'DAO', 'DAO-02', 'Art. 37 – Décret 2009-277', 'Spécifications techniques et critères de qualification', 'Les spécifications techniques sont neutres, non discriminatoires et vérifiables.', 'Cahier des charges, attestation de neutralité, comparaison de marché', 70, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(8, 'DAO', 'DAO-03', 'Art. 38, 39 – Décret 2009-277', 'Critères d\'évaluation et pondération', 'Les critères d\'évaluation des offres et leur pondération sont clairement définis dans le DAO avant lancement.', 'Grille d\'évaluation publiée dans le DAO, procès-verbal de validation interne', 80, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(9, 'DAO', 'DAO-04', 'Art. 40 – Décret 2009-277', 'Délai de remise des offres', 'Le délai minimal de remise des offres est respecté (30 jours minimum pour AOO, 15 jours pour AON).', 'Avis d\'appel d\'offres, dates de publication et de dépôt, calcul du délai', 90, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
	(10, 'DAO', 'DAO-05', 'Art. 41, 42 – Décret 2009-277', 'Publication de l\'avis d\'appel d\'offres', 'L\'avis est publié dans les supports obligatoires (JBO, site ARMP, journal national).', 'Coupures de presse, capture d\'écran site ARMP, récépissés de publication', 100, '2026-04-02 21:31:50', '2026-04-02 21:31:50'),
