-- Listage de la structure de déclencheur fruitiva. trg_om_reference
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER `trg_om_reference`
BEFORE INSERT ON `ordre_missions`
FOR EACH ROW
BEGIN
    DECLARE v_seq INT;
    IF NEW.reference_om IS NULL OR NEW.reference_om = '' THEN
        SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(reference_om, '-', -1) AS UNSIGNED)), 0) + 1
        INTO v_seq
        FROM `ordre_missions`
        WHERE reference_om LIKE CONCAT('OM-', YEAR(NOW()), '-%');
        SET NEW.reference_om = CONCAT('OM-', YEAR(NOW()), '-', LPAD(v_seq, 3, '0'));
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Listage de la structure de déclencheur fruitiva. tr_audit_process_scores_after_insert
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO';
DELIMITER //
CREATE TRIGGER IF NOT EXISTS `tr_audit_process_scores_after_insert`
AFTER INSERT ON `audit_process_scores`
FOR EACH ROW
BEGIN
  CALL `sp_recalculate_audit_ranking`(NEW.process_id, NEW.entity_id);
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Listage de la structure de déclencheur fruitiva. tr_audit_process_scores_after_update
SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO';
DELIMITER //
CREATE TRIGGER IF NOT EXISTS `tr_audit_process_scores_after_update`
AFTER UPDATE ON `audit_process_scores`
FOR EACH ROW
BEGIN
  IF OLD.score != NEW.score THEN
    CALL `sp_recalculate_audit_ranking`(NEW.process_id, NEW.entity_id);
  END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `vw_audit_process_evaluation_current`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_audit_process_evaluation_current` AS SELECT 
  apr.id as ranking_id,
  p.id as process_id,
  p.code,
  p.name as process_name,
  e.id as entity_id,
  e.name as entity_name,
  apr.total_score,
  apr.average_score,
  apr.rating_label,
  apr.ranking_position,
  apr.ranking_percentage,
  apr.priority_status,
  apr.last_evaluation_date,
  apr.number_of_evaluations,
  COUNT(aps.id) as factors_evaluated
FROM `audit_process_rankings` apr
LEFT JOIN `processes` p ON apr.process_id = p.id
LEFT JOIN `entities` e ON apr.entity_id = e.id
LEFT JOIN `audit_process_scores` aps ON aps.process_id = p.id AND aps.entity_id = e.id
GROUP BY apr.id, p.id, e.id
ORDER BY e.id, apr.average_score DESC ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `vw_audit_process_rankings_stats`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_audit_process_rankings_stats` AS SELECT 
  e.id as entity_id,
  e.name as entity_name,
  COUNT(apr.id) as total_processes,
  SUM(CASE WHEN apr.rating_label = 'Excellent' THEN 1 ELSE 0 END) as excellent_count,
  SUM(CASE WHEN apr.rating_label = 'Très Bon' THEN 1 ELSE 0 END) as very_good_count,
  SUM(CASE WHEN apr.rating_label = 'Bon' THEN 1 ELSE 0 END) as good_count,
  SUM(CASE WHEN apr.rating_label = 'Moyen' THEN 1 ELSE 0 END) as medium_count,
  SUM(CASE WHEN apr.rating_label = 'Faible' THEN 1 ELSE 0 END) as weak_count,
  SUM(CASE WHEN apr.priority_status = 'Critique' THEN 1 ELSE 0 END) as critical_count,
  ROUND(AVG(apr.average_score), 2) as avg_score,
  MAX(apr.average_score) as max_score,
  MIN(apr.average_score) as min_score
FROM `audit_process_rankings` apr
LEFT JOIN `entities` e ON apr.entity_id = e.id
GROUP BY e.id, e.name
ORDER BY e.name ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `vw_audit_process_scores_detail`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_audit_process_scores_detail` AS SELECT 
  aps.id,
  p.id as process_id,
  p.code,
  p.name as process_name,
  e.id as entity_id,
  e.name as entity_name,
  af.id as factor_id,
  af.label as factor_label,
  af.order_position,
  afs.value as scale_value,
  afs.label as scale_label,
  aps.score,
  aps.notes,
  aps.score_date
FROM `audit_process_scores` aps
LEFT JOIN `processes` p ON aps.process_id = p.id
LEFT JOIN `entities` e ON aps.entity_id = e.id
LEFT JOIN `audit_factors` af ON aps.factor_id = af.id
LEFT JOIN `audit_factor_scales` afs ON aps.score = afs.value
WHERE af.is_active = 1
ORDER BY e.id, p.id, af.order_position ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_amq_marche_synthese`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_amq_marche_synthese` AS SELECT
    m.id                                                        AS marche_id,
    m.amq_id,
    m.reference,
    m.intitule,
    m.attributaire,
    m.montant,

    -- Score étapes
    COUNT(DISTINCT e.id)                                        AS nb_etapes,
    SUM(CASE WHEN e.statut = 'oui'         THEN 1 ELSE 0 END)  AS etapes_oui,
    SUM(CASE WHEN e.statut = 'non'         THEN 1 ELSE 0 END)  AS etapes_non,
    SUM(CASE WHEN e.statut = 'sans_objet'  THEN 1 ELSE 0 END)  AS etapes_so,
    SUM(CASE WHEN e.statut IS NULL         THEN 1 ELSE 0 END)  AS etapes_non_renseignees,

    -- Score objectifs
    COUNT(DISTINCT o.id)                                        AS nb_objectifs,
    SUM(CASE WHEN o.atteint = 'oui'     THEN 1 ELSE 0 END)     AS obj_oui,
    SUM(CASE WHEN o.atteint = 'non'     THEN 1 ELSE 0 END)     AS obj_non,
    SUM(CASE WHEN o.atteint = 'partiel' THEN 1 ELSE 0 END)     AS obj_partiel,

    -- Taux conformité étapes (hors sans_objet)
    ROUND(
        SUM(CASE WHEN e.statut = 'oui' THEN 1 ELSE 0 END)
        / NULLIF(SUM(CASE WHEN e.statut IN ('oui','non') THEN 1 ELSE 0 END), 0)
        * 100, 1
    )                                                           AS taux_conformite_pct

FROM  `amq_marches`  m
LEFT JOIN `amq_etapes`   e ON e.marche_id = m.id
LEFT JOIN `amq_objectifs` o ON o.marche_id = m.id
GROUP BY m.id, m.amq_id, m.reference, m.intitule, m.attributaire, m.montant ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_amq_synthese`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_amq_synthese` AS SELECT
    a.id                                                        AS amq_id,
    a.code,
    a.intitule_qem,
    a.assignment_id,
    a.mission_id,
    a.validation_status,
    a.fait_par,
    a.date_fait,

    COUNT(DISTINCT m.id)                                        AS nb_marches,
    COUNT(DISTINCT e.id)                                        AS nb_etapes_total,
    SUM(CASE WHEN e.statut = 'oui'        THEN 1 ELSE 0 END)   AS etapes_oui,
    SUM(CASE WHEN e.statut = 'non'        THEN 1 ELSE 0 END)   AS etapes_non,
    SUM(CASE WHEN e.statut = 'sans_objet' THEN 1 ELSE 0 END)   AS etapes_so,

    COUNT(DISTINCT o.id)                                        AS nb_objectifs_total,
    SUM(CASE WHEN o.atteint = 'oui'     THEN 1 ELSE 0 END)     AS obj_oui,
    SUM(CASE WHEN o.atteint = 'non'     THEN 1 ELSE 0 END)     AS obj_non,
    SUM(CASE WHEN o.atteint = 'partiel' THEN 1 ELSE 0 END)     AS obj_partiel,

    COUNT(DISTINCT d.id)                                        AS nb_documents

FROM  `mission_phase_amq`  a
LEFT JOIN `amq_marches`    m ON m.amq_id    = a.id
LEFT JOIN `amq_etapes`     e ON e.amq_id    = a.id
LEFT JOIN `amq_objectifs`  o ON o.amq_id    = a.id
LEFT JOIN `amq_documents`  d ON d.amq_id    = a.id
GROUP BY a.id, a.code, a.intitule_qem, a.assignment_id,
         a.mission_id, a.validation_status, a.fait_par, a.date_fait ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_apt_summary`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_apt_summary` AS SELECT
  a.id, a.code, a.mission_id, a.assignment_id, a.intitule_proc, a.validation_status,
  COUNT(DISTINCT p.id) AS nb_procedures,
  COUNT(DISTINCT l.id) AS nb_niveaux,
  COUNT(DISTINCT d.id) AS nb_documents,
  COUNT(DISTINCT CASE WHEN i.resultat='c'  AND i.is_section=0 THEN i.id END) AS nb_c,
  COUNT(DISTINCT CASE WHEN i.resultat='nc' AND i.is_section=0 THEN i.id END) AS nb_nc,
  COUNT(DISTINCT CASE WHEN i.resultat='pp' AND i.is_section=0 THEN i.id END) AS nb_pp,
  COUNT(DISTINCT CASE WHEN i.is_section=0 THEN i.id END) AS nb_items,
  a.created_at, a.updated_at
FROM mission_phase_apt a
LEFT JOIN apt_procedures      p ON p.apt_id=a.id
LEFT JOIN apt_test_levels     l ON l.apt_id=a.id
LEFT JOIN apt_level_documents d ON d.apt_id=a.id
LEFT JOIN apt_matrice_items   i ON i.apt_id=a.id
GROUP BY a.id ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_conformite_dashboard`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_conformite_dashboard` AS SELECT
    ac.id                                               AS form_id,
    ac.intitule_qcc,
    ac.date_audit,
    ac.statut,
    ac.score_global,
    COUNT(aci.id)                                       AS total_exigences,
    SUM(CASE WHEN aci.reponse = 'O'  THEN 1 ELSE 0 END) AS total_conformes,
    SUM(CASE WHEN aci.reponse = 'N'  THEN 1 ELSE 0 END) AS total_non_conformes,
    SUM(CASE WHEN aci.reponse = 'SO' THEN 1 ELSE 0 END) AS total_sans_objet,
    SUM(CASE WHEN aci.reponse IS NULL THEN 1 ELSE 0 END) AS total_non_evalues,
    ROUND(AVG(CASE WHEN aci.reponse IS NOT NULL THEN aci.score END), 2) AS taux_conformite,
    COUNT(DISTINCT p.id)                                 AS nb_propositions_ia,
    COUNT(DISTINCT CASE WHEN p.type = 'alerte' THEN p.id END) AS nb_alertes_ia
FROM analyse_conformites ac
LEFT JOIN analyse_conformite_items aci ON aci.analyse_conformite_id = ac.id
LEFT JOIN ia_propositions p            ON p.item_id = aci.id
GROUP BY
    ac.id, ac.intitule_qcc, ac.date_audit, ac.statut, ac.score_global ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_fiche_synthese_frap`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_fiche_synthese_frap` AS SELECT 
  sf.id AS synthese_id,
  sf.fiche_test_id,
  sf.mission_id,
  sf.assignment_id,
  sf.objectif_controle,
  sf.rubrique,
  sf.sous_rubrique,
  sf.ordre_rubrique,
  sf.ordre_sous_rubrique,
  frap.id AS frap_id,
  frap.num_frap,
  frap.niveau_controle_interne,
  frap.fait_constats,
  frap.probleme,
  frap.causes,
  frap.impacts,
  frap.recommandation,
  frap.commentaires_audite,
  frap.points_forts,
  frap.date_echeance,
  frap.personne_responsable,
  frap.livrable,
  sfi.ordre AS ordre_frap
FROM fiche_synthese_frap sf
JOIN fiche_synthese_frap_items sfi ON sfi.synthese_id = sf.id
JOIN fiche_observation_frap frap ON frap.id = sfi.frap_id
ORDER BY sf.ordre_rubrique, sf.ordre_sous_rubrique, sfi.ordre ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_outils_par_procedure`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_outils_par_procedure` AS SELECT fto.fiche_test_id, fto.mission_id, fto.procedure_code, fto.test_ref, fto.obj_num,
  GROUP_CONCAT(DISTINCT fto.outil_code ORDER BY fto.outil_code SEPARATOR ',') AS outils,
  COUNT(DISTINCT fto.outil_code) AS nb_outils,
  AVG(fto.ia_score) AS score_ia_moyen,
  MAX(fto.updated_at) AS derniere_maj
FROM fiche_test_outils fto WHERE fto.is_current = 1
GROUP BY fto.fiche_test_id, fto.mission_id, fto.procedure_code, fto.test_ref, fto.obj_num ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_plan_action_priorite`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_plan_action_priorite` AS SELECT
  f.id AS frap_id,
  f.num_frap,
  f.rubrique,
  f.sous_rubrique,
  f.objectif_controle,
  f.probleme,
  f.recommandation,
  f.personne_responsable,
  f.date_echeance,
  f.priorite,
  f.statut AS frap_statut,
  f.mission_id,
  f.assignment_id,
  f.test_ref,
  f.obj_num,
  s.id AS suivi_id,
  s.statut AS suivi_statut,
  s.taux_realisation,
  s.commentaire,
  s.date_verification,
  DATEDIFF(CURDATE(), f.date_echeance) AS jours_retard,
  CASE
    WHEN f.date_echeance < CURDATE() AND (s.statut IS NULL OR s.statut NOT IN ('realise')) THEN 'depasse'
    WHEN f.date_echeance >= CURDATE() AND f.date_echeance <= DATE_ADD(CURDATE(), INTERVAL 7 DAY) THEN 'proche'
    ELSE 'ok'
  END AS alerte_echeance
FROM fiche_observation_frap f
LEFT JOIN plan_action_suivi s ON s.frap_id = f.id
WHERE f.deleted_at IS NULL ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_resultats_mission`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_resultats_mission` AS SELECT ft.id, ft.mission_id, ft.assignment_id, ft.validation_status,
  ia.score_global, ia.fiabilite,
  COUNT(DISTINCT fto.procedure_code) AS nb_procedures,
  COUNT(DISTINCT fto.id) AS nb_usages_outils
FROM mission_phase_fiche_test ft
LEFT JOIN fiche_test_outils fto ON fto.fiche_test_id=ft.id AND fto.is_current=1
LEFT JOIN fiche_test_ia_global ia ON ia.fiche_test_id=ft.id AND ia.is_current=1
GROUP BY ft.id ;

-- Suppression de la table temporaire et création finale de la structure de VIEW
DROP TABLE IF EXISTS `v_reunion_cloture_full`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_reunion_cloture_full` AS SELECT
  rc.id                  AS rc_id,
  rc.mission_id,
  rc.code,
  rc.statut,
  rc.date_reunion,
  ft.id                  AS fiche_test_id,
  ft.validation_status   AS ft_statut,
  ft.auditeur_id,
  ia.score_global        AS ia_score,
  ia.conclusion          AS ia_conclusion,
  COUNT(DISTINCT frap.id)AS nb_fraps
FROM reunion_clotures rc
LEFT JOIN mission_phase_fiche_test ft  ON ft.mission_id = rc.mission_id
LEFT JOIN fiche_test_ia_global ia      ON ia.fiche_test_id = ft.id AND ia.is_current = 1
LEFT JOIN fiche_observation_frap frap  ON frap.mission_id = rc.mission_id AND frap.deleted_at IS NULL
GROUP BY rc.id, ft.id ;

